import { json } from '../_shared/http.js';
import { createContext, readEnv } from '../_shared/context.js';
import { processDueJobs } from '../_shared/jobs.js';
import { timingSafeEqual } from '../_shared/crypto-token.js';

function authorized(request, env) {
  const header = request.headers.get('Authorization') || '';
  const bearer = header.startsWith('Bearer ') ? header.slice(7) : '';
  const custom = request.headers.get('X-Worker-Secret') || '';
  const secret = env.WORKER_SECRET || '';
  if (!secret) return false;
  return timingSafeEqual(bearer, secret) || timingSafeEqual(custom, secret);
}

Deno.serve(async (request) => {
  if (request.method === 'OPTIONS') return new Response(null, { status: 204 });
  if (request.method !== 'POST') return json({ error: 'Method not allowed.' }, 405);

  try {
    const ctx = await createContext(readEnv());
    if (!authorized(request, ctx.env)) return json({ error: 'Unauthorized.' }, 401);
    const result = await processDueJobs(ctx.env, ctx.store, { fetchImpl: fetch, limit: 20 });
    return json({ ok: true, ...result });
  } catch {
    return json({ error: 'Worker failed.' }, 500);
  }
});

/**
 * CORS, JSON, OPTIONS, and request-size helpers. CORS is not authentication.
 */

export const MAX_JSON_BYTES = 32 * 1024;
export const MAX_WEBHOOK_BYTES = 256 * 1024;

/**
 * @param {string} [raw]
 * @returns {string[]}
 */
export function parseOriginAllowlist(raw) {
  return String(raw || '')
    .split(',')
    .map((item) => item.trim().replace(/\/$/, ''))
    .filter(Boolean);
}

/**
 * @param {Request} request
 * @param {string[]} allowlist
 * @returns {string}
 */
const LOCAL_STOREFRONT = /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/i;
const VERCEL_STOREFRONT = /^https:\/\/ld-frontend(?:-[a-z0-9-]+)?\.vercel\.app$/i;

export function pickAllowOrigin(request, allowlist) {
  const origin = request.headers.get('Origin') || '';
  const normalized = origin.replace(/\/$/, '');
  if (allowlist.includes(normalized)) return origin;
  if (LOCAL_STOREFRONT.test(normalized)) return origin;
  if (VERCEL_STOREFRONT.test(normalized)) return origin;
  if (!origin && allowlist.length) return allowlist[0];
  return '';
}

/**
 * Stripe success/cancel must land on the origin that holds the capability token.
 * Only SITE_URL, CORS allowlist, and local static-server origins are accepted.
 * @param {object} env
 * @param {string} [origin]
 */
export function checkoutReturnOrigin(env, origin) {
  const site = String(env?.SITE_URL || 'https://like-dealer.com').replace(/\/$/, '');
  const candidate = String(origin || '')
    .trim()
    .replace(/\/$/, '');
  if (!candidate) return site;
  if (LOCAL_STOREFRONT.test(candidate)) return candidate;
  if (VERCEL_STOREFRONT.test(candidate)) return candidate;
  const allowlist = parseOriginAllowlist(env?.CORS_ALLOW_ORIGINS || site);
  if (allowlist.includes(candidate) || candidate === site) return candidate;
  return site;
}

/**
 * @param {Request} request
 * @param {object} env
 */
export function corsHeaders(request, env) {
  const site = String(env.SITE_URL || 'https://like-dealer.com').replace(/\/$/, '');
  const allowlist = parseOriginAllowlist(
    env.CORS_ALLOW_ORIGINS || `${site},https://ld-frontend-phi.vercel.app,http://localhost:3000,http://127.0.0.1:3000`
  );
  if (site && !allowlist.includes(site)) allowlist.push(site);
  if (!allowlist.includes('https://ld-frontend-phi.vercel.app')) {
    allowlist.push('https://ld-frontend-phi.vercel.app');
  }
  const allowOrigin = pickAllowOrigin(request, allowlist);
  /** @type {Record<string, string>} */
  const headers = {
    Vary: 'Origin',
    'Access-Control-Allow-Methods': 'GET,POST,OPTIONS',
    'Access-Control-Allow-Headers':
      'Authorization, Content-Type, X-Checkout-Token, X-Worker-Secret, Stripe-Signature, apikey',
    'Access-Control-Max-Age': '86400',
  };
  if (allowOrigin) headers['Access-Control-Allow-Origin'] = allowOrigin;
  return headers;
}

/**
 * @param {unknown} body
 * @param {number} status
 * @param {Record<string, string>} [headers]
 */
export function json(body, status = 200, headers = {}) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'Content-Type': 'application/json; charset=utf-8',
      ...headers,
    },
  });
}

/**
 * @param {Request} request
 */
export function clientIp(request) {
  return (
    request.headers.get('cf-connecting-ip') ||
    request.headers.get('x-forwarded-for')?.split(',')[0]?.trim() ||
    request.headers.get('x-real-ip') ||
    'unknown'
  );
}

/**
 * @param {Request} request
 * @param {number} maxBytes
 * @returns {Promise<{ ok: true, text: string }|{ ok: false, error: string }>}
 */
export async function readTextLimited(request, maxBytes) {
  const declared = Number(request.headers.get('content-length') || 0);
  if (declared > maxBytes) return { ok: false, error: 'Request is too large.' };
  const reader = request.body?.getReader?.();
  if (!reader) {
    const text = await request.text();
    if (text.length > maxBytes) return { ok: false, error: 'Request is too large.' };
    return { ok: true, text };
  }
  const chunks = [];
  let size = 0;
  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    size += value.byteLength;
    if (size > maxBytes) return { ok: false, error: 'Request is too large.' };
    chunks.push(value);
  }
  const bytes = new Uint8Array(size);
  let offset = 0;
  chunks.forEach((chunk) => {
    bytes.set(chunk, offset);
    offset += chunk.byteLength;
  });
  return { ok: true, text: new TextDecoder().decode(bytes) };
}

/**
 * @param {Request} request
 * @param {number} [maxBytes]
 */
export async function readJsonBody(request, maxBytes = MAX_JSON_BYTES) {
  const limited = await readTextLimited(request, maxBytes);
  if (!limited.ok) return { ok: false, error: limited.error };
  if (!limited.text) return { ok: true, value: {} };
  try {
    return { ok: true, value: JSON.parse(limited.text), raw: limited.text };
  } catch {
    return { ok: false, error: 'Invalid JSON body.' };
  }
}

/**
 * @param {Request} request
 */
export function readCapabilityToken(request, body = {}) {
  return (
    request.headers.get('X-Checkout-Token') ||
    request.headers.get('x-checkout-token') ||
    (typeof body.capabilityToken === 'string' ? body.capabilityToken : '') ||
    ''
  );
}

/**
 * @param {Request} [request]
 */
export function correlationId(request) {
  const header = request?.headers?.get('x-request-id') || request?.headers?.get('x-correlation-id');
  return header && header.length < 128 ? header : crypto.randomUUID();
}

/**
 * @param {typeof fetch} fetchImpl
 * @param {string} url
 * @param {RequestInit} [init]
 * @param {number} [timeoutMs]
 */
export async function fetchWithTimeout(fetchImpl, url, init = {}, timeoutMs = 15000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetchImpl(url, { ...init, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

/**
 * Shared Edge Function bootstrap. Deno.env is read only here.
 * Optional public.app_secrets rows fill blanks; non-empty Deno.env wins.
 */

import { createClient } from 'npm:@supabase/supabase-js@2.57.4';
import { createSupabaseStore } from './store-supabase.js';
import { corsHeaders, json } from './http.js';

const ENV_KEYS = Object.freeze([
  'SUPABASE_URL',
  'SUPABASE_ANON_KEY',
  'SUPABASE_SERVICE_ROLE_KEY',
  'SITE_URL',
  'CORS_ALLOW_ORIGINS',
  'RETAIL_CURRENCY',
  'PROVIDER_CURRENCY',
  'FX_PROVIDER_TO_RETAIL',
  'MARKUP_MULTIPLIER',
  'RETAIL_CATALOGUE_URL',
  'RETAIL_SOCIALPANEL_IDS',
  'SOCIALPANEL24_API_KEY',
  'SOCIALPANEL24_TIMEOUT_MS',
  'SOCIALPANEL24_ENABLED',
  'PROVIDER_ENV',
  'STRIPE_SECRET_KEY',
  'STRIPE_WEBHOOK_SECRET',
  'RESEND_API_KEY',
  'FROM_EMAIL',
  'FROM_NAME',
  'REPLY_TO_EMAIL',
  'OWNER_EMAIL',
  'SUPPORT_EMAIL',
  'WORKER_SECRET',
  'ORDER_ID_PREFIX',
  'CATALOGUE_TIMEOUT_MS',
  'APP_FUNCTIONS_URL',
  'APP_ENV',
  'ALLOW_LIVE_PROVIDER',
  'PROVIDER_ADAPTER',
  'STRIPE_API_VERSION',
  'STRIPE_TIMEOUT_MS',
  'RESEND_TIMEOUT_MS',
  'RESEND_WEBHOOK_SECRET',
  'MIN_CONTRIBUTION_MINOR',
]);

const DENO_ONLY = new Set(['SUPABASE_URL', 'SUPABASE_ANON_KEY', 'SUPABASE_SERVICE_ROLE_KEY']);

/**
 * @returns {Record<string, string>}
 */
export function readEnv() {
  const env = {};
  for (const key of ENV_KEYS) {
    const value = Deno.env.get(key);
    if (value != null) env[key] = value;
  }
  return env;
}

/**
 * Merge optional database secrets under process env.
 * @param {Record<string, string>} env
 * @param {Record<string, string>} extra
 */
export function mergeEnv(env, extra) {
  const merged = {};
  Object.entries(extra || {}).forEach(([key, value]) => {
    if (!ENV_KEYS.includes(key) || DENO_ONLY.has(key)) return;
    if (value) merged[key] = String(value);
  });
  Object.entries(env || {}).forEach(([key, value]) => {
    if (value != null && value !== '') merged[key] = String(value);
  });
  return merged;
}

export function createServiceClient(env = readEnv()) {
  return createClient(env.SUPABASE_URL, env.SUPABASE_SERVICE_ROLE_KEY, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export async function createContext(env = readEnv()) {
  const client = createServiceClient(env);
  const store = createSupabaseStore(client);
  let extra = {};
  try {
    extra = await store.listAppSecrets();
  } catch {
    extra = {};
  }
  return { env: mergeEnv(env, extra), store };
}

export function withCors(request, env, result) {
  const headers = corsHeaders(request, env);
  if (result instanceof Response) {
    const next = new Headers(result.headers);
    Object.entries(headers).forEach(([key, value]) => next.set(key, value));
    return new Response(result.body, { status: result.status, headers: next });
  }
  return json(result.body, result.status, headers);
}

/**
 * Job worker: emails, fulfilment, and status polling. Authenticated separately
 * from guest browsers. Cron every minute is the durable fallback.
 */

import { formatMoney } from './money.js';
import { customerPaymentEmail, ownerAlertEmail, ownerPaymentEmail } from './email-templates.js';
import { resendIdempotencyExpired, sendResendEmail } from './email.js';
import { fulfillPaidOrder, isPollingTerminal, pollProviderOrders } from './fulfillment.js';
import { pollRefillStatuses, requestOrderRefill, REFILL_TERMINAL } from './refill.js';
import { logError } from './log.js';

export const JOB_TASKS = Object.freeze([
  'fulfill',
  'poll_status',
  'poll_provider_status',
  'purge_rate_limits',
  'email_customer_payment',
  'email_owner_payment',
  'email_owner_alert',
  'provider_refill',
  'poll_refill_status',
]);

function backoffMs(attempts) {
  const exp = Math.min(Math.max(Number(attempts) || 1, 1), 12);
  const base = Math.min(60 * 60 * 1000, 1000 * 2 ** exp);
  const jitter = Math.floor(Math.random() * Math.min(1000, base / 4));
  return base + jitter;
}

function maxAttempts(job) {
  return Number(job.max_attempts) > 0 ? Number(job.max_attempts) : 12;
}

function exhausted(job) {
  return Number(job.attempts || 0) >= maxAttempts(job);
}

async function noteAttempt(store, job) {
  if (typeof store.recordJobAttempt !== 'function') return;
  try {
    await store.recordJobAttempt({
      jobId: job.id,
      orderId: job.order_id,
      task: job.task,
      attempt: job.attempts,
      outcome: 'claimed',
    });
  } catch {
    /* job_attempts may be missing on older databases */
  }
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} job
 * @param {object} [deps]
 */
export async function processJob(env, store, job, deps = {}) {
  const order = job.order_id ? await store.getOrderById(job.order_id) : null;

  if (job.task === 'fulfill') {
    if (!order) {
      await store.failJob(job.id, { reason: 'missing_order' }, new Date().toISOString(), true);
      return;
    }
    await fulfillPaidOrder(env, store, order, job, deps);
    return;
  }

  if (job.task === 'poll_status' || job.task === 'poll_provider_status') {
    if (job.task === 'poll_provider_status') {
      await pollProviderOrders(env, store, deps);
    }
    await settlePollJob(env, store, job, order, deps);
    return;
  }

  if (job.task === 'purge_rate_limits') {
    if (typeof store.purgeRateLimits === 'function') {
      await store.purgeRateLimits();
    }
    await store.completeJob(job.id, { purged: true });
    return;
  }

  if (job.task === 'email_customer_payment' || job.task === 'email_owner_payment' || job.task === 'email_owner_alert') {
    if (!order) {
      await store.failJob(job.id, { reason: 'missing_order' }, new Date().toISOString(), true);
      return;
    }
    await sendJobEmail(env, store, job, order, deps);
    return;
  }

  if (job.task === 'provider_refill') {
    if (!order) {
      await store.failJob(job.id, { reason: 'missing_order' }, new Date().toISOString(), true);
      return;
    }
    await requestOrderRefill(env, store, order, job, deps);
    return;
  }

  if (job.task === 'poll_refill_status') {
    await pollRefillStatuses(env, store, deps);
    await settleRefillPollJob(store, job);
    return;
  }

  await store.skipJob(job.id, { reason: 'unknown_task' });
}

async function settlePollJob(env, store, job, order, deps) {
  if (job.task === 'poll_status' && order) {
    const latest = await store.getOrderById(order.id);
    if (latest && isPollingTerminal(latest.fulfillment_status)) {
      await store.completeJob(job.id, { status: latest.fulfillment_status, coalesced: true });
      return;
    }
    await store.enqueueJob({
      orderId: null,
      task: 'poll_provider_status',
      dedupeKey: 'poll:batch',
    });
    await store.completeJob(job.id, { coalesced: true });
    return;
  }

  const remaining = (await store.listPollingOrders()).filter(
    (row) => row.provider_order_id && !isPollingTerminal(row.fulfillment_status)
  );
  if (!remaining.length) {
    await store.completeJob(job.id, { polled: 0, drained: true });
    return;
  }
  const next = new Date(Date.now() + Math.max(60_000, backoffMs(job.attempts))).toISOString();
  await store.failJob(job.id, { reason: 'requeue_poll', remaining: remaining.length }, next, exhausted(job));
}

async function settleRefillPollJob(store, job) {
  const remaining =
    typeof store.listRefillPollingOrders === 'function'
      ? (await store.listRefillPollingOrders()).filter(
          (row) => row.provider_refill_id && !REFILL_TERMINAL.includes(row.provider_refill_status)
        )
      : [];
  if (!remaining.length) {
    await store.completeJob(job.id, { polled: 0, drained: true });
    return;
  }
  const next = new Date(Date.now() + Math.max(60_000, backoffMs(job.attempts))).toISOString();
  await store.failJob(job.id, { reason: 'requeue_refill_poll', remaining: remaining.length }, next, exhausted(job));
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} job
 * @param {object} order
 * @param {object} deps
 */
async function sendJobEmail(env, store, job, order, deps) {
  const payload = job.payload && typeof job.payload === 'object' ? { ...job.payload } : {};

  if (job.external_ref && (payload.acceptedAt || job.outcome?.acceptedAt)) {
    await store.completeJob(job.id, { already: true }, job.external_ref);
    return;
  }

  const attemptedAt = payload.attemptedAt || job.outcome?.payload?.attemptedAt;
  if (attemptedAt && !job.external_ref) {
    const attempted = new Date(attemptedAt);
    if (!resendIdempotencyExpired(attempted, new Date())) {
      await store.failJob(
        job.id,
        { reason: 'ambiguous_resend_window', payload },
        new Date(Date.now() + 10 * 60 * 1000).toISOString(),
        exhausted(job)
      );
      return;
    }
  }

  const amountLabel = formatMoney(order.amount_minor, order.currency);
  const mapped = {
    ...order,
    displayId: order.display_id,
    serviceLabel: order.service_snapshot?.label,
    paymentStatus: order.payment_status,
    fulfillmentStatus: order.fulfillment_status,
    customerEmail: order.email,
    serviceId: order.service_id,
    providerOrderId: order.provider_order_id,
  };

  let rendered;
  let to = '';
  if (job.task === 'email_customer_payment') {
    rendered = customerPaymentEmail(mapped, {
      amountLabel,
      supportEmail: env.SUPPORT_EMAIL || env.REPLY_TO_EMAIL,
      siteUrl: env.SITE_URL,
    });
    to = order.email;
  } else if (job.task === 'email_owner_payment') {
    rendered = ownerPaymentEmail(mapped, { amountLabel });
    to = env.OWNER_EMAIL;
  } else {
    rendered = ownerAlertEmail(mapped, payload.alert || 'Operator attention required.');
    to = env.OWNER_EMAIL;
  }

  if (!to) {
    await store.skipJob(job.id, { reason: 'missing_recipient' });
    return;
  }

  const idempotencyKey = job.dedupe_key;
  const nextPayload = {
    ...payload,
    to,
    subject: rendered.subject,
    templateVersion: rendered.templateVersion,
    idempotencyKey,
    attemptedAt: new Date().toISOString(),
  };
  if (typeof store.updateJobPayload === 'function') {
    await store.updateJobPayload(job.id, nextPayload);
  }

  if (typeof store.recordExternalAttempt === 'function') {
    await store.recordExternalAttempt({
      orderId: order.id,
      jobId: job.id,
      vendor: 'resend',
      action: 'send',
      fingerprint: idempotencyKey,
      attemptedAt: nextPayload.attemptedAt,
    });
  }

  try {
    const result = await sendResendEmail(
      env,
      { to, subject: rendered.subject, html: rendered.html, text: rendered.text, idempotencyKey },
      deps.fetchImpl
    );
    await store.completeJob(job.id, { accepted: true, payload: { ...nextPayload, acceptedAt: new Date().toISOString() } }, result.id);
    if (job.task === 'email_customer_payment') {
      await store.updateOrder(order.id, { customer_email_state: 'accepted' });
    }
  } catch (err) {
    logError('email send failed', { task: job.task });
    if (job.task === 'email_customer_payment') {
      await store.updateOrder(order.id, { customer_email_state: 'failed' });
    }
    const retryable = err && typeof err === 'object' && /** @type {{ retryable?: boolean }} */ (err).retryable === true;
    await store.failJob(
      job.id,
      { error: 'send_failed', payload: nextPayload },
      new Date(Date.now() + backoffMs(job.attempts)).toISOString(),
      exhausted(job) || !retryable
    );
  }
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} [deps]
 */
export async function processDueJobs(env, store, deps = {}) {
  const workerId = deps.workerId || crypto.randomUUID();
  const claimed = await store.claimJobs(workerId, deps.limit || 20);
  const pollJobs = claimed.filter((job) => job.task === 'poll_status' || job.task === 'poll_provider_status');
  const refillPollJobs = claimed.filter((job) => job.task === 'poll_refill_status');
  const others = claimed.filter(
    (job) => job.task !== 'poll_status' && job.task !== 'poll_provider_status' && job.task !== 'poll_refill_status'
  );
  const results = [];

  if (pollJobs.length) {
    try {
      await pollProviderOrders(env, store, deps);
    } catch (err) {
      logError('poll batch failed', { name: err instanceof Error ? err.name : 'error' });
    }
    for (const job of pollJobs) {
      try {
        await noteAttempt(store, job);
        const order = job.order_id ? await store.getOrderById(job.order_id) : null;
        await settlePollJob(env, store, job, order, deps);
        results.push({ id: job.id, task: job.task, ok: true });
      } catch (err) {
        logError('job failed', { task: job.task });
        await store.failJob(
          job.id,
          { error: 'exception' },
          new Date(Date.now() + backoffMs(job.attempts)).toISOString(),
          exhausted(job)
        );
        results.push({ id: job.id, task: job.task, ok: false });
      }
    }
  }

  if (refillPollJobs.length) {
    try {
      await pollRefillStatuses(env, store, deps);
    } catch (err) {
      logError('refill poll batch failed', { name: err instanceof Error ? err.name : 'error' });
    }
    for (const job of refillPollJobs) {
      try {
        await noteAttempt(store, job);
        await settleRefillPollJob(store, job);
        results.push({ id: job.id, task: job.task, ok: true });
      } catch (err) {
        logError('job failed', { task: job.task });
        await store.failJob(
          job.id,
          { error: 'exception' },
          new Date(Date.now() + backoffMs(job.attempts)).toISOString(),
          exhausted(job)
        );
        results.push({ id: job.id, task: job.task, ok: false });
      }
    }
  }

  for (const job of others) {
    try {
      await noteAttempt(store, job);
      await processJob(env, store, job, deps);
      results.push({ id: job.id, task: job.task, ok: true });
    } catch (err) {
      logError('job failed', { task: job.task });
      await store.failJob(
        job.id,
        { error: 'exception' },
        new Date(Date.now() + backoffMs(job.attempts)).toISOString(),
        exhausted(job)
      );
      results.push({ id: job.id, task: job.task, ok: false });
    }
  }
  return { workerId, processed: results.length, results };
}

/**
 * Checkout capability tokens. The raw token never belongs in logs or URLs.
 */

const encoder = new TextEncoder();

/**
 * Hash a capability token with SHA-256. Hex-encoded.
 * @param {string} token
 * @returns {Promise<string>}
 */
export async function hashCapabilityToken(token) {
  const value = String(token || '');
  if (!value) throw new Error('Missing capability token');
  const digest = await crypto.subtle.digest('SHA-256', encoder.encode(value));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Constant-time string compare.
 * @param {string} a
 * @param {string} b
 * @returns {boolean}
 */
export function timingSafeEqual(a, b) {
  const left = String(a);
  const right = String(b);
  if (left.length !== right.length) return false;
  let out = 0;
  for (let i = 0; i < left.length; i += 1) {
    out |= left.charCodeAt(i) ^ right.charCodeAt(i);
  }
  return out === 0;
}

/**
 * SHA-256 hex digest of an arbitrary string.
 * @param {string} value
 * @returns {Promise<string>}
 */
export async function sha256Hex(value) {
  const digest = await crypto.subtle.digest('SHA-256', encoder.encode(String(value)));
  return [...new Uint8Array(digest)].map((b) => b.toString(16).padStart(2, '0')).join('');
}

/**
 * Supabase repository. All writes use the service-role client from Edge Functions.
 */

import { applySupabaseOrderFilters } from './admin-orders.js';

export function createSupabaseStore(client, clock = () => new Date()) {
  const store = {
    async transaction(fn) {
      return fn(store);
    },

    async getOrderById(id) {
      const { data, error } = await client.from('orders').select('*').eq('id', id).maybeSingle();
      if (error) throw error;
      return data;
    },

    async getOrderByAttempt(attemptId) {
      const { data, error } = await client
        .from('orders')
        .select('*')
        .eq('checkout_attempt_id', attemptId)
        .maybeSingle();
      if (error) throw error;
      return data;
    },

    async getOrderBySession(sessionId) {
      const { data, error } = await client
        .from('orders')
        .select('*')
        .eq('stripe_session_id', sessionId)
        .maybeSingle();
      if (error) throw error;
      return data;
    },

    async getOrderByTokenHash(hash, lookup) {
      let query = client.from('orders').select('*').eq('capability_token_hash', hash);
      if (lookup.orderId) query = query.eq('id', lookup.orderId);
      else if (lookup.sessionId) query = query.eq('stripe_session_id', lookup.sessionId);
      else if (lookup.attemptId) query = query.eq('checkout_attempt_id', lookup.attemptId);
      else return null;
      const { data, error } = await query.maybeSingle();
      if (error) throw error;
      return data;
    },

    async insertOrder(order) {
      const { data, error } = await client.from('orders').insert(order).select('*').single();
      if (error) throw error;
      return data;
    },

    async updateOrder(id, patch) {
      const { data, error } = await client
        .from('orders')
        .update({ ...patch, updated_at: clock().toISOString() })
        .eq('id', id)
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async insertStripeEvent(eventId, eventType, livemode) {
      const { error } = await client.from('stripe_events').insert({
        event_id: eventId,
        event_type: eventType,
        livemode,
      });
      if (error && error.code === '23505') return { duplicate: true };
      if (error) throw error;
      return { duplicate: false };
    },

    async applyPaymentEvent(args) {
      const { data, error } = await client.rpc('apply_stripe_payment_event', {
        p_event_id: args.eventId,
        p_event_type: args.eventType,
        p_livemode: args.livemode,
        p_order_id: args.orderId || null,
        p_session_id: args.sessionId || null,
        p_amount_minor: Number.isInteger(args.amountMinor) ? args.amountMinor : null,
        p_currency: args.currency,
        p_payment_intent_id: args.paymentIntentId || null,
        p_desired_payment: args.desiredPayment,
        p_object_id: args.objectId || null,
      });
      if (error) throw error;
      return data;
    },

    async enqueueJob({ orderId, task, dedupeKey, payload = {}, nextRetryAt }) {
      const { data, error } = await client
        .from('jobs')
        .upsert(
          {
            order_id: orderId,
            task,
            dedupe_key: dedupeKey,
            payload,
            next_retry_at: nextRetryAt || clock().toISOString(),
            status: 'pending',
          },
          { onConflict: 'dedupe_key', ignoreDuplicates: true }
        )
        .select('*')
        .maybeSingle();
      if (error) throw error;
      return data;
    },

    async claimJobs(workerId, limit, leaseMs = 55000) {
      const { data, error } = await client.rpc('claim_jobs', {
        p_worker_id: workerId,
        p_limit: limit,
        p_lease_ms: leaseMs,
      });
      if (error) throw error;
      return data || [];
    },

    async completeJob(id, outcome, externalRef) {
      const { data, error } = await client
        .from('jobs')
        .update({
          status: 'succeeded',
          outcome,
          external_ref: externalRef || null,
          lease_until: null,
          updated_at: clock().toISOString(),
        })
        .eq('id', id)
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async failJob(id, outcome, nextRetryAt, terminal = false) {
      const { data, error } = await client
        .from('jobs')
        .update({
          status: terminal ? 'failed' : 'pending',
          outcome,
          next_retry_at: nextRetryAt,
          lease_until: null,
          updated_at: clock().toISOString(),
        })
        .eq('id', id)
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async skipJob(id, outcome) {
      const { data, error } = await client
        .from('jobs')
        .update({
          status: 'skipped',
          outcome,
          lease_until: null,
          updated_at: clock().toISOString(),
        })
        .eq('id', id)
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async updateJobPayload(id, payload) {
      const { data: current, error: readError } = await client.from('jobs').select('payload').eq('id', id).single();
      if (readError) throw readError;
      const next = { ...(current?.payload || {}), ...payload };
      const { data, error } = await client
        .from('jobs')
        .update({ payload: next, updated_at: clock().toISOString() })
        .eq('id', id)
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async recordExternalAttempt(row) {
      const { data, error } = await client
        .from('external_requests')
        .insert({
          order_id: row.orderId || null,
          job_id: row.jobId || null,
          vendor: row.vendor,
          action: row.action,
          fingerprint: row.fingerprint || '',
          idempotency_key: row.idempotencyKey || null,
          attempted_at: row.attemptedAt || clock().toISOString(),
          outcome: row.outcome || 'attempted',
          external_ref: row.externalRef || null,
        })
        .select('*')
        .maybeSingle();
      if (error) throw error;
      return data;
    },

    async purgeRateLimits() {
      const cutoff = Math.floor(clock().getTime() / 1000) - 3600;
      const { error } = await client.from('rate_limits').delete().lt('window_start', cutoff);
      if (error) throw error;
      return { purged: true };
    },

    async operationalSnapshot() {
      const { data: jobRows } = await client.from('jobs').select('status');
      const { data: orderRows } = await client.from('orders').select('payment_status, fulfillment_status');
      const jobs = jobRows || [];
      const orders = orderRows || [];
      return {
        jobsPending: jobs.filter((job) => job.status === 'pending').length,
        jobsFailed: jobs.filter((job) => job.status === 'failed').length,
        jobsLeased: jobs.filter((job) => job.status === 'leased').length,
        unknownSubmissions: orders.filter((row) => row.fulfillment_status === 'submission_unknown').length,
        deferredFulfillment: orders.filter((row) => row.fulfillment_status === 'deferred').length,
        paidUnfulfilled: orders.filter(
          (row) => row.payment_status === 'paid' && !['completed', 'skipped_test_mode'].includes(row.fulfillment_status)
        ).length,
      };
    },

    async getJobByExternalRef(ref) {
      const { data, error } = await client.from('jobs').select('*').eq('external_ref', ref).maybeSingle();
      if (error) throw error;
      return data;
    },

    async getJobById(id) {
      const { data, error } = await client.from('jobs').select('*').eq('id', id).maybeSingle();
      if (error) throw error;
      return data;
    },

    async replayJob(id) {
      const { data: current, error: readError } = await client.from('jobs').select('attempts').eq('id', id).maybeSingle();
      if (readError) throw readError;
      if (!current) return null;
      const { data, error } = await client
        .from('jobs')
        .update({
          status: 'pending',
          next_retry_at: clock().toISOString(),
          attempts: Math.max(0, Number(current.attempts || 1) - 1),
          lease_until: null,
          updated_at: clock().toISOString(),
        })
        .eq('id', id)
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async recordJobAttempt(row) {
      const { data, error } = await client
        .from('job_attempts')
        .insert({
          job_id: row.jobId || null,
          order_id: row.orderId || null,
          task: row.task || '',
          attempt: row.attempt || 0,
          outcome: row.outcome || 'claimed',
          correlation_id: row.correlationId || null,
        })
        .select('*')
        .maybeSingle();
      if (error) throw error;
      return data;
    },

    async insertOperatorAction(row) {
      const { data, error } = await client
        .from('operator_actions')
        .upsert(
          {
            command: row.command,
            payload: row.payload || {},
            status: row.status,
            actor: row.actor || null,
            approver: row.approver || null,
            idempotency_key: row.idempotencyKey,
            executed_at: row.status === 'executed' ? clock().toISOString() : null,
          },
          { onConflict: 'idempotency_key' }
        )
        .select('*')
        .maybeSingle();
      if (error) throw error;
      return data;
    },

    async consumeRateLimit(bucket, key, limit, windowSec) {
      const { data, error } = await client.rpc('consume_rate_limit', {
        p_bucket: bucket,
        p_key: key,
        p_limit: limit,
        p_window_sec: windowSec,
      });
      if (error) throw error;
      return data;
    },

    async cacheGet(key) {
      const { data, error } = await client.from('catalogue_cache').select('*').eq('cache_key', key).maybeSingle();
      if (error) throw error;
      if (!data) return null;
      if (data.expires_at && new Date(data.expires_at).getTime() < clock().getTime()) return null;
      return data.payload;
    },

    async cacheSet(key, value, ttlMs) {
      const expires = new Date(clock().getTime() + ttlMs).toISOString();
      const { error } = await client.from('catalogue_cache').upsert({
        cache_key: key,
        payload: value,
        fetched_at: clock().toISOString(),
        expires_at: expires,
      });
      if (error) throw error;
    },

    async listPollingOrders() {
      const { data, error } = await client
        .from('orders')
        .select('*')
        .eq('payment_status', 'paid')
        .not('provider_order_id', 'is', null)
        .in('fulfillment_status', ['submitted', 'in_progress', 'dispatching'])
        .limit(100);
      if (error) throw error;
      return data || [];
    },

    async listRefillPollingOrders() {
      const { data, error } = await client
        .from('orders')
        .select('*')
        .not('provider_refill_id', 'is', null)
        .in('provider_refill_status', ['requested', 'pending'])
        .limit(100);
      if (error) throw error;
      return data || [];
    },

    async listOrders(query) {
      const from = (Number(query.page) - 1) * Number(query.pageSize);
      const to = from + Number(query.pageSize) - 1;
      let builder = client.from('orders').select('*', { count: 'exact' });
      builder = applySupabaseOrderFilters(builder, query);
      const { data, error, count } = await builder.range(from, to);
      if (error) throw error;
      return { rows: data || [], total: Number(count || 0) };
    },

    async listOrderEvents(orderId) {
      const { data, error } = await client
        .from('order_events')
        .select('*')
        .eq('order_id', orderId)
        .order('created_at', { ascending: false })
        .limit(200);
      if (error) throw error;
      return data || [];
    },

    async listOrderJobs(orderId) {
      const { data, error } = await client
        .from('jobs')
        .select('*')
        .eq('order_id', orderId)
        .order('created_at', { ascending: false })
        .limit(100);
      if (error) throw error;
      return data || [];
    },

    async listOrderExternalRequests(orderId) {
      const { data, error } = await client
        .from('external_requests')
        .select('*')
        .eq('order_id', orderId)
        .order('attempted_at', { ascending: false })
        .limit(100);
      if (error) throw error;
      return data || [];
    },

    async appendOrderEvent({ orderId, actor, action, fromState, toState, reason }) {
      const { data, error } = await client
        .from('order_events')
        .insert({
          order_id: orderId,
          actor: actor || 'admin',
          action,
          from_state: fromState || null,
          to_state: toState || null,
          reason: reason || null,
        })
        .select('*')
        .maybeSingle();
      if (error) throw error;
      return data;
    },

    async listProducts() {
      const { data, error } = await client
        .from('products')
        .select('*')
        .order('sort_order', { ascending: true })
        .order('id', { ascending: true });
      if (error) throw error;
      return data || [];
    },

    async listAppSecrets() {
      const { data, error } = await client.from('app_secrets').select('name, value');
      if (error) throw error;
      /** @type {Record<string, string>} */
      const extra = {};
      (data || []).forEach((row) => {
        if (row?.name && row?.value) extra[row.name] = String(row.value);
      });
      return extra;
    },

    async getAdminUser(userId) {
      const { data, error } = await client.from('admin_users').select('*').eq('user_id', userId).maybeSingle();
      if (error) throw error;
      return data;
    },

    async countAdmins() {
      const { count, error } = await client
        .from('admin_users')
        .select('user_id', { count: 'exact', head: true })
        .is('disabled_at', null);
      if (error) throw error;
      return Number(count || 0);
    },

    async insertAdminUser(row) {
      const { data, error } = await client
        .from('admin_users')
        .insert({
          user_id: row.user_id,
          email: row.email,
          role: row.role || 'admin',
          disabled_at: row.disabled_at || null,
        })
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async getFlag(name) {
      const { data, error } = await client.from('app_flags').select('*').eq('name', name).maybeSingle();
      if (error) throw error;
      return data;
    },

    async setFlag(name, enabled) {
      const { data, error } = await client
        .from('app_flags')
        .upsert({ name, enabled: Boolean(enabled), updated_at: clock().toISOString() }, { onConflict: 'name' })
        .select('*')
        .single();
      if (error) throw error;
      return data;
    },

    async getProduct(id) {
      const { data, error } = await client.from('products').select('*').eq('id', id).maybeSingle();
      if (error) throw error;
      return data;
    },

    async upsertProduct(row) {
      const { data, error } = await client.from('products').upsert(row, { onConflict: 'id' }).select('*').single();
      if (error) throw error;
      return data;
    },

    async deleteProduct(id) {
      const { data, error } = await client.from('products').delete().eq('id', id).select('*').maybeSingle();
      if (error) throw error;
      return data;
    },

    async bulkUpdateSortOrder(items) {
      const updates = Array.isArray(items) ? items : [];
      /** @type {any[]} */
      const next = [];
      for (const item of updates) {
        const { data, error } = await client
          .from('products')
          .update({ sort_order: item.sort_order })
          .eq('id', item.id)
          .select('*')
          .maybeSingle();
        if (error) throw error;
        if (data) next.push(data);
      }
      return next;
    },

    async insertProductAudit(row) {
      const { data, error } = await client
        .from('product_audit')
        .insert({
          actor_user_id: row.actor_user_id || null,
          actor_email: row.actor_email || null,
          action: row.action,
          product_id: row.product_id || null,
          before: row.before || null,
          after: row.after || null,
        })
        .select('*')
        .maybeSingle();
      if (error) throw error;
      return data;
    },
  };

  return store;
}

/**
 * Admin order list: field descriptors, query validation, and admin projection.
 * capability_token_hash never leaves the server.
 */

import { PAYMENT_STATES, FULFILLMENT_STATES } from './states.js';
import { refillEligibility } from './refill.js';

const RATE_UNITS = Object.freeze(['per_1000', 'per_unit', 'package', 'per_comment']);

export const CUSTOMER_EMAIL_STATES = Object.freeze([
  'unknown',
  'queued',
  'sent',
  'accepted',
  'delivered',
  'bounced',
  'failed',
]);

export const REFILL_STATES = Object.freeze([
  'requested',
  'pending',
  'completed',
  'rejected',
  'failed',
  'unknown',
]);

export const ORDER_SEARCH_FIELDS = Object.freeze([
  'display_id',
  'email',
  'provider_order_id',
  'stripe_session_id',
  'stripe_payment_intent_id',
]);

export const DEFAULT_PAGE_SIZE = 25;
export const MAX_PAGE_SIZE = 100;

const UUID_PATTERN =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const OPS = Object.freeze({
  text: Object.freeze(['eq', 'contains', 'is_null']),
  uuid: Object.freeze(['eq']),
  enum: Object.freeze(['eq', 'in', 'is_null']),
  int: Object.freeze(['eq', 'gte', 'lte']),
  numeric: Object.freeze(['eq', 'gte', 'lte']),
  bool: Object.freeze(['eq', 'is_null']),
  timestamp: Object.freeze(['eq', 'gte', 'lte']),
  json: Object.freeze([]),
});

/**
 * @param {string} type
 * @param {{ group: string, values?: readonly string[], list?: boolean, sortable?: boolean, filterable?: boolean }} spec
 */
function field(type, spec) {
  const filterable = spec.filterable ?? type !== 'json';
  const sortable = spec.sortable ?? type !== 'json';
  return Object.freeze({
    type,
    group: spec.group,
    sortable,
    filterable,
    list: Boolean(spec.list),
    operators: filterable ? OPS[type] : Object.freeze([]),
    values: spec.values || null,
  });
}

export const ORDER_FIELDS = Object.freeze({
  id: field('uuid', { group: 'order' }),
  display_id: field('text', { group: 'order', list: true }),
  checkout_attempt_id: field('uuid', { group: 'order' }),
  email: field('text', { group: 'customer', list: true }),
  service_id: field('text', { group: 'order', list: true }),
  service_snapshot: field('json', { group: 'order' }),
  provider_service_id: field('text', { group: 'provider' }),
  provider_type: field('text', { group: 'provider' }),
  provider_payload: field('json', { group: 'provider' }),
  quantity: field('int', { group: 'order' }),
  billable_quantity: field('int', { group: 'order' }),
  currency: field('text', { group: 'pricing', list: true }),
  amount_minor: field('int', { group: 'pricing', list: true }),
  quote_version: field('text', { group: 'pricing' }),
  rate_unit: field('enum', { group: 'order', values: RATE_UNITS }),
  retail_rate_minor: field('int', { group: 'pricing' }),
  markup: field('numeric', { group: 'pricing' }),
  inputs: field('json', { group: 'order' }),
  params_fingerprint: field('text', { group: 'order' }),
  payment_status: field('enum', { group: 'stripe', values: PAYMENT_STATES, list: true }),
  fulfillment_status: field('enum', { group: 'provider', values: FULFILLMENT_STATES, list: true }),
  stripe_session_id: field('text', { group: 'stripe' }),
  stripe_payment_intent_id: field('text', { group: 'stripe' }),
  stripe_livemode: field('bool', { group: 'stripe' }),
  checkout_revision: field('int', { group: 'order' }),
  provider_order_id: field('text', { group: 'provider', list: true }),
  provider_dispatched_at: field('timestamp', { group: 'provider' }),
  provider_status_raw: field('text', { group: 'provider' }),
  provider_charge: field('text', { group: 'provider' }),
  provider_currency: field('text', { group: 'provider' }),
  provider_start_count: field('text', { group: 'provider' }),
  provider_remains: field('text', { group: 'provider' }),
  provider_last_status_at: field('timestamp', { group: 'provider' }),
  created_at: field('timestamp', { group: 'order', list: true }),
  updated_at: field('timestamp', { group: 'order' }),
  customer_email_state: field('enum', { group: 'customer', values: CUSTOMER_EMAIL_STATES }),
  expected_provider_cost_minor: field('int', { group: 'pricing' }),
  expected_contribution_minor: field('int', { group: 'pricing' }),
  fx_provider_to_retail: field('numeric', { group: 'pricing' }),
  fx_quoted_at: field('timestamp', { group: 'pricing' }),
  stripe_integration_identifier: field('text', { group: 'stripe' }),
  min_contribution_minor: field('int', { group: 'pricing' }),
  provider_refill_id: field('text', { group: 'refill' }),
  provider_refill_status: field('enum', { group: 'refill', values: REFILL_STATES, list: true }),
  provider_refill_requested_at: field('timestamp', { group: 'refill' }),
  provider_refill_last_status_at: field('timestamp', { group: 'refill' }),
});

const HIDDEN_COLUMNS = Object.freeze(['capability_token_hash']);

/**
 * @param {Record<string, unknown>|null|undefined} order
 */
export function toAdminOrder(order) {
  if (!order || typeof order !== 'object') return null;
  /** @type {Record<string, unknown>} */
  const out = {};
  for (const name of Object.keys(ORDER_FIELDS)) {
    out[name] = order[name] === undefined ? null : order[name];
  }
  for (const hidden of HIDDEN_COLUMNS) {
    delete out[hidden];
  }
  return out;
}

function isUuid(value) {
  return typeof value === 'string' && UUID_PATTERN.test(value);
}

/**
 * @param {unknown} raw
 */
function normalizeFilterList(raw) {
  if (Array.isArray(raw)) return raw;
  if (raw && typeof raw === 'object') {
    return Object.entries(raw).map(([fieldName, spec]) => {
      if (spec && typeof spec === 'object' && !Array.isArray(spec)) {
        const item = /** @type {Record<string, unknown>} */ (spec);
        return { field: fieldName, op: item.op, value: item.value };
      }
      return { field: fieldName, op: 'eq', value: spec };
    });
  }
  return [];
}

function parseIntValue(value, errors, label) {
  if (typeof value === 'number' && Number.isInteger(value)) return value;
  if (typeof value === 'string' && /^-?\d+$/.test(value.trim())) return Number(value.trim());
  errors.push(`${label} must be an integer.`);
  return null;
}

function parseNumberValue(value, errors, label) {
  if (typeof value === 'number' && Number.isFinite(value)) return value;
  if (typeof value === 'string' && value.trim() && Number.isFinite(Number(value))) return Number(value);
  errors.push(`${label} must be a number.`);
  return null;
}

function parseTimestamp(value, errors, label) {
  const text = String(value ?? '').trim();
  if (!text || Number.isNaN(Date.parse(text))) {
    errors.push(`${label} must be an ISO timestamp.`);
    return null;
  }
  return text;
}

function parseBool(value, errors, label) {
  if (value === true || value === false) return value;
  const text = String(value ?? '').trim().toLowerCase();
  if (text === 'true' || text === '1') return true;
  if (text === 'false' || text === '0') return false;
  errors.push(`${label} must be a boolean.`);
  return null;
}

function sanitizeSearch(raw) {
  const text = String(raw ?? '').trim();
  if (!text) return '';
  return text.slice(0, 200).replace(/[^a-zA-Z0-9@.+_:\-\s]/g, '');
}

function parseFilterValue(spec, op, value, errors) {
  if (op === 'is_null') {
    const flag = parseBool(value == null ? true : value, errors, spec.type);
    return flag;
  }
  if (op === 'in') {
    const list = Array.isArray(value) ? value.map((item) => String(item)) : String(value ?? '').split(',').map((item) => item.trim()).filter(Boolean);
    if (!list.length) {
      errors.push(`Filter ${spec.type} requires at least one value.`);
      return [];
    }
    if (spec.values) {
      const allowed = new Set(spec.values);
      for (const item of list) {
        if (!allowed.has(item)) errors.push(`Unknown value for filter: ${item}`);
      }
    }
    return list;
  }
  if (spec.type === 'enum') {
    const text = String(value ?? '').trim();
    if (spec.values && !spec.values.includes(text)) {
      errors.push(`Unknown value for filter: ${text}`);
      return text;
    }
    return text;
  }
  if (spec.type === 'uuid') {
    const text = String(value ?? '').trim();
    if (!isUuid(text)) errors.push('Filter value must be a UUID.');
    return text;
  }
  if (spec.type === 'int') return parseIntValue(value, errors, 'Filter value');
  if (spec.type === 'numeric') return parseNumberValue(value, errors, 'Filter value');
  if (spec.type === 'timestamp') return parseTimestamp(value, errors, 'Filter value');
  if (spec.type === 'bool') return parseBool(value, errors, 'Filter value');
  const text = String(value ?? '');
  if (text.length > 200) errors.push('Filter value is too long.');
  return text;
}

/**
 * @param {Record<string, unknown>} body
 * @returns {{ ok: false, errors: string[] }|{ ok: true, value: {
 *   page: number,
 *   pageSize: number,
 *   sort: string,
 *   dir: 'asc'|'desc',
 *   q: string,
 *   filters: Array<{ field: string, op: string, value: unknown }>
 * } }}
 */
export function parseOrderQuery(body) {
  const errors = [];
  const row = body && typeof body === 'object' ? body : {};
  const page = parseIntValue(row.page ?? 1, errors, 'page') ?? 1;
  if (page < 1) errors.push('page must be ≥ 1.');
  const pageSize = parseIntValue(row.pageSize ?? row.page_size ?? DEFAULT_PAGE_SIZE, errors, 'pageSize') ?? DEFAULT_PAGE_SIZE;
  if (pageSize < 1 || pageSize > MAX_PAGE_SIZE) errors.push(`pageSize must be 1–${MAX_PAGE_SIZE}.`);

  const sort = String(row.sort ?? row.sortField ?? row.sort_field ?? 'created_at').trim();
  const spec = ORDER_FIELDS[sort];
  if (!spec || !spec.sortable) errors.push('Invalid sort field.');
  const dirRaw = String(row.dir ?? row.sortDir ?? row.sort_dir ?? 'desc').trim().toLowerCase();
  if (dirRaw !== 'asc' && dirRaw !== 'desc') errors.push('Sort direction must be asc or desc.');
  const dir = dirRaw === 'asc' ? 'asc' : 'desc';

  const q = sanitizeSearch(row.q);
  /** @type {Array<{ field: string, op: string, value: unknown }>} */
  const filters = [];
  for (const item of normalizeFilterList(row.filters)) {
    const fieldName = String(item?.field || '').trim();
    const fieldSpec = ORDER_FIELDS[fieldName];
    if (!fieldSpec || !fieldSpec.filterable) {
      errors.push(`Unknown or unfilterable field: ${fieldName || '(empty)'}`);
      continue;
    }
    const op = String(item?.op || 'eq').trim();
    if (!fieldSpec.operators.includes(op)) {
      errors.push(`Invalid operator ${op} for ${fieldName}.`);
      continue;
    }
    const value = parseFilterValue(fieldSpec, op, item?.value, errors);
    filters.push({ field: fieldName, op, value });
  }

  if (errors.length) return { ok: false, errors };
  return {
    ok: true,
    value: {
      page,
      pageSize,
      sort,
      dir,
      q,
      filters,
    },
  };
}

function escapeIlike(value) {
  return String(value).replace(/\\/g, '\\\\').replace(/%/g, '\\%').replace(/_/g, '\\_');
}

/**
 * @param {any} query
 * @param {ReturnType<typeof parseOrderQuery> extends { ok: true, value: infer V } ? V : never} parsed
 */
export function applySupabaseOrderFilters(query, parsed) {
  let next = query;
  for (const filter of parsed.filters) {
    if (filter.op === 'eq') next = next.eq(filter.field, filter.value);
    else if (filter.op === 'contains') next = next.ilike(filter.field, `%${escapeIlike(filter.value)}%`);
    else if (filter.op === 'in') next = next.in(filter.field, filter.value);
    else if (filter.op === 'gte') next = next.gte(filter.field, filter.value);
    else if (filter.op === 'lte') next = next.lte(filter.field, filter.value);
    else if (filter.op === 'is_null') {
      next = filter.value ? next.is(filter.field, null) : next.not(filter.field, 'is', null);
    }
  }
  if (parsed.q) {
    const term = escapeIlike(parsed.q);
    const clause = ORDER_SEARCH_FIELDS.map((name) => `${name}.ilike.%${term}%`).join(',');
    next = next.or(clause);
  }
  return next
    .order(parsed.sort, { ascending: parsed.dir === 'asc', nullsFirst: false })
    .order('id', { ascending: true });
}

function compareValues(a, b, type) {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  if (type === 'int' || type === 'numeric') return Number(a) - Number(b);
  if (type === 'timestamp') return Date.parse(String(a)) - Date.parse(String(b));
  if (type === 'bool') return Number(Boolean(a)) - Number(Boolean(b));
  return String(a).localeCompare(String(b));
}

function matchesFilter(row, filter) {
  const current = row[filter.field];
  if (filter.op === 'eq') {
    if (typeof filter.value === 'boolean') return Boolean(current) === filter.value && current != null;
    return String(current ?? '') === String(filter.value ?? '');
  }
  if (filter.op === 'contains') {
    return String(current ?? '').toLowerCase().includes(String(filter.value ?? '').toLowerCase());
  }
  if (filter.op === 'in') {
    return Array.isArray(filter.value) && filter.value.map(String).includes(String(current ?? ''));
  }
  if (filter.op === 'gte') return compareValues(current, filter.value, ORDER_FIELDS[filter.field].type) >= 0;
  if (filter.op === 'lte') return compareValues(current, filter.value, ORDER_FIELDS[filter.field].type) <= 0;
  if (filter.op === 'is_null') return filter.value ? current == null : current != null;
  return false;
}

/**
 * @param {any[]} rows
 * @param {ReturnType<typeof parseOrderQuery> extends { ok: true, value: infer V } ? V : never} parsed
 */
export function applyMemoryOrderQuery(rows, parsed) {
  const filtered = rows.filter((row) => {
    if (!parsed.filters.every((filter) => matchesFilter(row, filter))) return false;
    if (!parsed.q) return true;
    const needle = parsed.q.toLowerCase();
    return ORDER_SEARCH_FIELDS.some((name) => String(row[name] || '').toLowerCase().includes(needle));
  });
  const spec = ORDER_FIELDS[parsed.sort];
  filtered.sort((a, b) => {
    const cmp = compareValues(a[parsed.sort], b[parsed.sort], spec.type);
    const ordered = parsed.dir === 'asc' ? cmp : -cmp;
    if (ordered) return ordered;
    return String(a.id).localeCompare(String(b.id));
  });
  const total = filtered.length;
  const start = (parsed.page - 1) * parsed.pageSize;
  return { rows: filtered.slice(start, start + parsed.pageSize), total };
}

function projectJob(job) {
  if (!job) return null;
  return {
    id: job.id,
    task: job.task,
    status: job.status,
    attempts: job.attempts,
    max_attempts: job.max_attempts,
    next_retry_at: job.next_retry_at,
    outcome: job.outcome,
    external_ref: job.external_ref,
    created_at: job.created_at,
    updated_at: job.updated_at,
  };
}

function projectEvent(row) {
  return {
    id: row.id,
    actor: row.actor,
    action: row.action,
    from_state: row.from_state,
    to_state: row.to_state,
    reason: row.reason,
    created_at: row.created_at,
  };
}

function projectRequest(row) {
  return {
    id: row.id,
    vendor: row.vendor,
    action: row.action,
    outcome: row.outcome,
    external_ref: row.external_ref || row.externalRef || null,
    attempted_at: row.attempted_at || row.attemptedAt || null,
    created_at: row.created_at,
  };
}

/**
 * @param {object} env
 * @param {object} store
 * @param {Record<string, unknown>} body
 */
export async function handleOrdersList(env, store, body) {
  const parsed = parseOrderQuery(body);
  if (!parsed.ok) return { status: 400, body: { ok: false, error: parsed.errors[0], errors: parsed.errors } };
  const result = await store.listOrders(parsed.value);
  return {
    status: 200,
    body: {
      ok: true,
      rows: (result.rows || []).map(toAdminOrder),
      total: Number(result.total || 0),
      page: parsed.value.page,
      pageSize: parsed.value.pageSize,
      sort: parsed.value.sort,
      dir: parsed.value.dir,
      fields: ORDER_FIELDS,
    },
  };
}

/**
 * @param {object} env
 * @param {object} store
 * @param {Record<string, unknown>} body
 * @param {object} extras
 */
export async function handleOrdersGet(env, store, body, extras = {}) {
  const orderId = String(body.orderId || body.id || '').trim();
  if (!isUuid(orderId)) return { status: 400, body: { ok: false, error: 'Order id is required.' } };
  const order = await store.getOrderById(orderId);
  if (!order) return { status: 404, body: { ok: false, error: 'Order not found.' } };
  const [events, jobs, requests, refill] = await Promise.all([
    store.listOrderEvents(orderId),
    store.listOrderJobs(orderId),
    store.listOrderExternalRequests(orderId),
    refillEligibility(env, store, order, extras),
  ]);
  return {
    status: 200,
    body: {
      ok: true,
      order: toAdminOrder(order),
      refill,
      events: (events || []).map(projectEvent),
      jobs: (jobs || []).map(projectJob),
      requests: (requests || []).map(projectRequest),
      fields: ORDER_FIELDS,
    },
  };
}

/**
 * @param {object} env
 * @param {object} store
 * @param {Record<string, unknown>} body
 * @param {{ id: string, email?: string }} actor
 * @param {object} extras
 */
export async function handleOrdersRefill(env, store, body, actor, extras = {}) {
  const orderId = String(body.orderId || body.id || '').trim();
  if (!isUuid(orderId)) return { status: 400, body: { ok: false, error: 'Order id is required.' } };
  const order = await store.getOrderById(orderId);
  if (!order) return { status: 404, body: { ok: false, error: 'Order not found.' } };
  const eligibility = await refillEligibility(env, store, order, extras);
  if (!eligibility.eligible) {
    return { status: 409, body: { ok: false, error: eligibility.reason || 'Refill is not available.', refill: eligibility } };
  }

  const requestedAt = extras.now ? new Date(extras.now()).toISOString() : new Date().toISOString();
  await store.updateOrder(order.id, {
    provider_refill_status: 'requested',
    provider_refill_requested_at: requestedAt,
  });
  await store.enqueueJob({
    orderId: order.id,
    task: 'provider_refill',
    dedupeKey: `refill:${order.id}:${requestedAt}`,
  });
  if (typeof store.appendOrderEvent === 'function') {
    await store.appendOrderEvent({
      orderId: order.id,
      actor: actor.email || actor.id || 'admin',
      action: 'admin.refill_requested',
      reason: 'Admin requested a SocialPanel24 refill.',
    });
  }
  const latest = await store.getOrderById(order.id);
  return {
    status: 202,
    body: {
      ok: true,
      accepted: true,
      order: toAdminOrder(latest),
      refill: { eligible: false, reason: 'refill_in_flight' },
    },
  };
}

export { isUuid };

/**
 * Decimal-safe money helpers. Rounding is half-up via Math.round after
 * scaling to currency minor units. Rate units are explicit per service;
 * nothing here assumes USD or per-1,000 globally.
 */

/** @type {Readonly<Record<string, number>>} */
export const CURRENCY_EXPONENTS = Object.freeze({
  USD: 2,
  EUR: 2,
  GBP: 2,
  AUD: 2,
  CAD: 2,
  JPY: 0,
});

/** @typedef {'per_1000'|'per_unit'|'package'|'per_comment'} RateUnit */

/**
 * ISO-4217 exponent for a currency code.
 * @param {string} currency
 * @returns {number}
 */
export function currencyExponent(currency) {
  const code = String(currency || '').trim().toUpperCase();
  if (Object.prototype.hasOwnProperty.call(CURRENCY_EXPONENTS, code)) {
    return CURRENCY_EXPONENTS[code];
  }
  return 2;
}

/**
 * @param {string} currency
 * @returns {number}
 */
export function minorFactor(currency) {
  return 10 ** currencyExponent(currency);
}

/**
 * Parse a decimal amount into integer minor units.
 * @param {unknown} value
 * @param {string} currency
 * @returns {number|null}
 */
export function parseDecimalToMinor(value, currency) {
  if (value == null || value === '') return null;
  const num = typeof value === 'number' ? value : Number(String(value).trim());
  if (!Number.isFinite(num) || num < 0) return null;
  return Math.round(num * minorFactor(currency));
}

/**
 * Convert integer minor units back to a major-unit number.
 * @param {number} minor
 * @param {string} currency
 * @returns {number}
 */
export function minorToMajor(minor, currency) {
  const value = Math.round(Number(minor));
  return value / minorFactor(currency);
}

/**
 * Apply a markup multiplier (≥ 1) to integer minor units.
 * @param {number} minor
 * @param {number} markup
 * @returns {number}
 */
export function applyMarkup(minor, markup) {
  const amount = Math.round(Number(minor));
  const factor = Number(markup);
  if (!Number.isInteger(amount) || amount < 0 || !Number.isFinite(factor) || factor < 1) {
    throw new Error('Invalid markup inputs');
  }
  return Math.round(amount * factor);
}

/**
 * Convert minor units between currencies using an explicit rate
 * (units of `to` per 1 unit of `from`). Same-currency rate is 1.
 * @param {number} minor
 * @param {string} fromCurrency
 * @param {string} toCurrency
 * @param {number} rateFromTo
 * @returns {number}
 */
export function convertMinor(minor, fromCurrency, toCurrency, rateFromTo) {
  const amount = Math.round(Number(minor));
  if (!Number.isInteger(amount) || amount < 0) {
    throw new Error('Invalid conversion amount');
  }
  const from = String(fromCurrency || '').toUpperCase();
  const to = String(toCurrency || '').toUpperCase();
  if (from === to) return amount;
  const rate = Number(rateFromTo);
  if (!Number.isFinite(rate) || rate <= 0) {
    throw new Error('Currency conversion rate is not configured');
  }
  const major = minorToMajor(amount, from);
  return parseDecimalToMinor(major * rate, to) ?? 0;
}

/**
 * Billable total in retail minor units.
 * @param {{
 *   rateMinor: number,
 *   quantity: number,
 *   rateUnit: RateUnit,
 *   packageMinor?: number
 * }} params
 * @returns {number}
 */
export function quoteTotalMinor(params) {
  const rateMinor = Math.round(Number(params.rateMinor));
  const quantity = Math.round(Number(params.quantity));
  const unit = params.rateUnit;
  if (!Number.isInteger(rateMinor) || rateMinor < 0) {
    throw new Error('Invalid rate');
  }
  if (unit === 'package') {
    const pkg = params.packageMinor == null ? rateMinor : Math.round(Number(params.packageMinor));
    if (!Number.isInteger(pkg) || pkg < 0) throw new Error('Invalid package price');
    return pkg;
  }
  if (!Number.isInteger(quantity) || quantity < 1) {
    throw new Error('Invalid quantity');
  }
  if (unit === 'per_1000') {
    return Math.round((rateMinor * quantity) / 1000);
  }
  if (unit === 'per_unit' || unit === 'per_comment') {
    return rateMinor * quantity;
  }
  throw new Error(`Unsupported rate unit: ${unit}`);
}

/**
 * Format minor units for display.
 * @param {number} minor
 * @param {string} currency
 * @param {string} [locale='en-US']
 * @returns {string}
 */
export function formatMoney(minor, currency, locale = 'en-US') {
  const value = Math.round(Number(minor));
  const code = String(currency || 'USD').toUpperCase();
  if (!Number.isInteger(value)) return '';
  return new Intl.NumberFormat(locale, {
    style: 'currency',
    currency: code,
  }).format(minorToMajor(value, code));
}

/**
 * Stable quote identity for mismatch comparison.
 * @param {{ amountMinor: number, currency: string, quantity: number, rateUnit: string, serviceId: string }} quote
 * @returns {string}
 */
export function quoteVersion(quote) {
  return [
    quote.serviceId,
    quote.quantity,
    quote.amountMinor,
    String(quote.currency || '').toUpperCase(),
    quote.rateUnit,
  ].join(':');
}

/**
 * HTML/plain-text email templates. Values are escaped. Provider secrets and
 * costs never appear in customer copy.
 */

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

