/**
 * Resend adapter. Idempotency keys last 24 hours; local sent records are kept
 * longer and ambiguous attempts outside that window must be reconciled first.
 */

import { logError } from './log.js';
import { fetchWithTimeout } from './http.js';

const RESEND_URL = 'https://api.resend.com/emails';
export const RESEND_IDEMPOTENCY_HOURS = 24;
const RESEND_TIMEOUT_MS = 15000;

/**
 * @param {object} env
 * @param {{
 *   to: string,
 *   subject: string,
 *   html: string,
 *   text: string,
 *   idempotencyKey: string
 * }} message
 * @param {typeof fetch} [fetchImpl]
 */
export async function sendResendEmail(env, message, fetchImpl = fetch) {
  const timeoutMs = Number(env.RESEND_TIMEOUT_MS || RESEND_TIMEOUT_MS);
  const response = await fetchWithTimeout(
    fetchImpl,
    RESEND_URL,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${env.RESEND_API_KEY}`,
        'Content-Type': 'application/json',
        'Idempotency-Key': message.idempotencyKey,
      },
      body: JSON.stringify({
        from: env.FROM_NAME ? `${env.FROM_NAME} <${env.FROM_EMAIL}>` : env.FROM_EMAIL,
        to: [message.to],
        subject: message.subject,
        html: message.html,
        text: message.text,
        reply_to: env.REPLY_TO_EMAIL || env.FROM_EMAIL,
      }),
    },
    timeoutMs
  );

  const json = await response.json().catch(() => ({}));
  if (!response.ok) {
    logError('resend failed', { status: response.status });
    const err = new Error(`Resend HTTP ${response.status}`);
    err.status = response.status;
    err.retryable = response.status >= 500 || response.status === 429;
    throw err;
  }
  return { id: String(json.id || ''), raw: json };
}

/**
 * "Accepted for sending" is not delivery. We store accepted + resend id.
 * @param {Date} sentAt
 * @param {Date} now
 */
export function resendIdempotencyExpired(sentAt, now) {
  const delta = now.getTime() - sentAt.getTime();
  return delta > RESEND_IDEMPOTENCY_HOURS * 60 * 60 * 1000;
}

/**
 * Paid-order submission and status polling. The customer's browser is not required.
 *
 * Duplicate prevention: SocialPanel24 has no client idempotency key. After
 * dispatch intent is persisted, ambiguous outcomes become submission_unknown
 * and never automatic-add again.
 *
 * Live provider HTTP runs only when Stripe livemode, PROVIDER_ENV=live,
 * SOCIALPANEL24_ENABLED=true, and APP_ENV=production (or ALLOW_LIVE_PROVIDER).
 */

import { addProviderOrder, fetchProviderStatuses, SocialPanelError } from './socialpanel24.js';
import { mapProviderStatus } from './states.js';
import { ownerAlertEmail } from './email-templates.js';
import { logError } from './log.js';

export const POLL_MAX_AGE_MS = 14 * 24 * 60 * 60 * 1000;
export const POLL_BATCH_SIZE = 100;

function providerEnv(env, fetchImpl) {
  return {
    apiKey: env.SOCIALPANEL24_API_KEY,
    fetchImpl,
    timeoutMs: Number(env.SOCIALPANEL24_TIMEOUT_MS || 15000),
  };
}

/**
 * @param {object} env
 * @param {object} order
 * @returns {{ action: 'live'|'fake'|'skip_test'|'defer', reason: string }}
 */
export function providerDispatchGate(env, order) {
  const stripeLive = order.stripe_livemode === true;
  const providerLive = String(env.PROVIDER_ENV || '').trim().toLowerCase() === 'live';
  const enabled = String(env.SOCIALPANEL24_ENABLED || '').trim().toLowerCase() === 'true';
  const appEnv = String(env.APP_ENV || env.DEPLOYMENT_ENV || '').trim().toLowerCase();
  const production = appEnv === 'production' || appEnv === 'prod';
  const allowLive = String(env.ALLOW_LIVE_PROVIDER || '').trim().toLowerCase() === 'true';
  const adapter = String(env.PROVIDER_ADAPTER || '').trim().toLowerCase();

  if (adapter === 'fake') return { action: 'fake', reason: 'fake_adapter' };
  if (!stripeLive) return { action: 'skip_test', reason: 'test_stripe' };
  if (!enabled) return { action: 'defer', reason: 'provider_disabled' };
  if (!providerLive) return { action: 'defer', reason: 'provider_not_live' };
  if (!production && !allowLive) return { action: 'defer', reason: 'non_production' };
  return { action: 'live', reason: '' };
}

/** @deprecated use providerDispatchGate */
export function liveProviderBlocked(env, order) {
  const gate = providerDispatchGate(env, order);
  if (gate.action === 'live' || gate.action === 'fake') return '';
  if (gate.action === 'skip_test') return 'test_stripe_live_provider';
  return gate.reason;
}

function fakeAddResult(order) {
  const suffix = String(order.id || '0').replace(/[^0-9]/g, '').slice(-8) || '1';
  return { orderId: `9${suffix.padStart(7, '0')}`.slice(0, 8), fake: true };
}

async function recordAttempt(store, row) {
  if (typeof store.recordExternalAttempt === 'function') {
    await store.recordExternalAttempt(row);
  }
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} order
 * @param {object} job
 * @param {object} [deps]
 */
export async function fulfillPaidOrder(env, store, order, job, deps = {}) {
  if (order.payment_status !== 'paid') {
    await store.skipJob(job.id, { reason: 'not_paid' });
    return { skipped: true, reason: 'not_paid' };
  }

  if (order.provider_order_id) {
    await store.enqueueJob({
      orderId: order.id,
      task: 'poll_provider_status',
      dedupeKey: 'poll:batch',
    });
    await store.completeJob(job.id, { reason: 'already_submitted' });
    return { skipped: true, reason: 'already_submitted' };
  }

  if (order.fulfillment_status === 'submission_unknown') {
    await store.skipJob(job.id, { reason: 'submission_unknown' });
    return { skipped: true, reason: 'submission_unknown' };
  }

  if (order.fulfillment_status === 'dispatching') {
    await store.updateOrder(order.id, { fulfillment_status: 'submission_unknown' });
    await store.enqueueJob({
      orderId: order.id,
      task: 'email_owner_alert',
      dedupeKey: `email:owner:unknown_submission:${order.id}`,
      payload: { alert: 'Expired lease after dispatch. Reconcile in SocialPanel24 before any resubmission.' },
    });
    await store.skipJob(job.id, { reason: 'lease_expired_after_dispatch' });
    return { skipped: true, reason: 'lease_expired_after_dispatch' };
  }

  if (order.fulfillment_status === 'blocked_balance') {
    await store.skipJob(job.id, { reason: 'blocked_balance' });
    return { skipped: true, reason: 'blocked_balance' };
  }

  if (typeof store.cacheGet === 'function') {
    const kill = await store.cacheGet('ops:provider_kill');
    if (kill && kill.enabled === false) {
      await store.updateOrder(order.id, { fulfillment_status: 'deferred' });
      const next = new Date(Date.now() + 5 * 60 * 1000).toISOString();
      await store.failJob(job.id, { reason: 'provider_kill_switch' }, next, false);
      return { skipped: true, deferred: true, reason: 'provider_kill_switch' };
    }
  }

  const gate = providerDispatchGate(env, order);
  if (gate.action === 'skip_test') {
    await store.updateOrder(order.id, { fulfillment_status: 'skipped_test_mode' });
    await store.completeJob(job.id, { reason: gate.reason });
    return { skipped: true, reason: gate.reason };
  }
  if (gate.action === 'defer') {
    await store.updateOrder(order.id, { fulfillment_status: 'deferred' });
    const next = new Date(Date.now() + 5 * 60 * 1000).toISOString();
    await store.failJob(job.id, { reason: gate.reason }, next, false);
    return { skipped: true, deferred: true, reason: gate.reason };
  }

  await store.updateOrder(order.id, {
    fulfillment_status: 'dispatching',
    provider_dispatched_at: new Date().toISOString(),
  });

  const payload = {
    service: String(order.provider_service_id),
    ...(order.provider_payload || {}),
  };

  await recordAttempt(store, {
    orderId: order.id,
    jobId: job.id,
    vendor: 'socialpanel24',
    action: 'add',
    fingerprint: JSON.stringify({ service: payload.service, quantity: payload.quantity }),
    attemptedAt: new Date().toISOString(),
  });

  try {
    const result =
      gate.action === 'fake'
        ? fakeAddResult(order)
        : await addProviderOrder(providerEnv(env, deps.fetchImpl), payload);
    await store.updateOrder(order.id, {
      provider_order_id: result.orderId,
      fulfillment_status: 'submitted',
    });
    await store.enqueueJob({
      orderId: null,
      task: 'poll_provider_status',
      dedupeKey: 'poll:batch',
    });
    await store.completeJob(job.id, { providerOrderId: result.orderId }, result.orderId);
    return { ok: true, providerOrderId: result.orderId };
  } catch (err) {
    const code = err instanceof SocialPanelError ? err.code : 'TRANSPORT';
    if (code === 'INSUFFICIENT_BALANCE') {
      await store.updateOrder(order.id, { fulfillment_status: 'blocked_balance' });
      await store.enqueueJob({
        orderId: order.id,
        task: 'email_owner_alert',
        dedupeKey: `email:owner:blocked_balance:${order.id}`,
        payload: { alert: 'SocialPanel24 rejected the order for insufficient balance. Customer charge is unchanged.' },
      });
      await store.completeJob(job.id, { reason: 'blocked_balance' });
      return { ok: false, reason: 'blocked_balance' };
    }
    if (code === 'PROVIDER_REJECTED') {
      await store.updateOrder(order.id, { fulfillment_status: 'failed' });
      await store.enqueueJob({
        orderId: order.id,
        task: 'email_owner_alert',
        dedupeKey: `email:owner:provider_rejected:${order.id}`,
        payload: { alert: `Provider rejected the order: ${err instanceof Error ? err.message : 'rejected'}` },
      });
      await store.completeJob(job.id, { reason: 'provider_rejected' });
      return { ok: false, reason: 'provider_rejected' };
    }

    await store.updateOrder(order.id, { fulfillment_status: 'submission_unknown' });
    await store.enqueueJob({
      orderId: order.id,
      task: 'email_owner_alert',
      dedupeKey: `email:owner:unknown_submission:${order.id}`,
      payload: {
        alert:
          'Provider submission is unknown. Search SocialPanel24 by time/link and attach the provider order id, or confirm non-acceptance before any resubmission. Automatic add retries are disabled.',
      },
    });
    await store.completeJob(job.id, { reason: 'submission_unknown', code });
    logError('fulfillment unknown', { code });
    return { ok: false, reason: 'submission_unknown' };
  }
}

export function isPollingTerminal(status) {
  return ['completed', 'failed', 'cancelled', 'partial', 'review', 'skipped_test_mode'].includes(status);
}

export function isPollExpired(order, now = Date.now()) {
  const started = Date.parse(order.provider_dispatched_at || order.created_at || '') || 0;
  return started > 0 && now - started > POLL_MAX_AGE_MS;
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} [deps]
 */
export async function pollProviderOrders(env, store, deps = {}) {
  const orders = await store.listPollingOrders();
  const active = orders.filter((row) => row.provider_order_id && !isPollingTerminal(row.fulfillment_status));
  const due = active.filter((row) => !isPollExpired(row));
  const ids = due.map((row) => row.provider_order_id).filter(Boolean);
  if (!ids.length) return { polled: 0 };

  const batches = [];
  for (let i = 0; i < ids.length; i += POLL_BATCH_SIZE) batches.push(ids.slice(i, i + POLL_BATCH_SIZE));

  let polled = 0;
  for (const batch of batches) {
    let result;
    try {
      result = await fetchProviderStatuses(providerEnv(env, deps.fetchImpl), batch);
    } catch (err) {
      logError('status batch failed', { size: batch.length });
      continue;
    }
    for (const order of due.filter((row) => batch.includes(row.provider_order_id))) {
      const entry = result[order.provider_order_id];
      if (!entry) continue;
      polled += 1;
      if (entry.error) {
        await store.updateOrder(order.id, {
          provider_status_raw: String(entry.error),
          provider_last_status_at: new Date().toISOString(),
        });
        continue;
      }
      const mapped = mapProviderStatus(entry.status);
      await store.updateOrder(order.id, {
        fulfillment_status: mapped === 'review' ? 'review' : mapped,
        provider_status_raw: String(entry.status || ''),
        provider_charge: entry.charge != null ? String(entry.charge) : order.provider_charge,
        provider_currency: entry.currency != null ? String(entry.currency) : order.provider_currency,
        provider_start_count: entry.start_count != null ? String(entry.start_count) : order.provider_start_count,
        provider_remains: entry.remains != null ? String(entry.remains) : order.provider_remains,
        provider_last_status_at: new Date().toISOString(),
      });
    }
  }

  for (const order of active.filter((row) => isPollExpired(row) && row.fulfillment_status !== 'review')) {
    await store.updateOrder(order.id, { fulfillment_status: 'review' });
    await store.enqueueJob({
      orderId: order.id,
      task: 'email_owner_alert',
      dedupeKey: `email:owner:stale_poll:${order.id}`,
      payload: { alert: 'Provider status polling reached the maximum age. Review the order manually.' },
    });
  }

  return { polled };
}

export { ownerAlertEmail };

/**
 * SocialPanel24 refill: eligibility, provider call, and refill-status polling.
 * Ambiguous refill outcomes become `unknown` and are never auto-retried.
 */

import { getProviderCatalog } from './catalogue.js';
import { providerDispatchGate } from './fulfillment.js';
import { findProviderService } from './pricing.js';
import { logError } from './log.js';
import { SocialPanelError, fetchProviderRefillStatuses, requestProviderRefill } from './socialpanel24.js';

export const REFILL_IN_FLIGHT = Object.freeze(['requested', 'pending']);
export const REFILL_ELIGIBLE_FULFILLMENT = Object.freeze(['completed', 'partial']);
export const REFILL_TERMINAL = Object.freeze(['completed', 'rejected', 'failed', 'unknown']);

function providerEnv(env, fetchImpl) {
  return {
    apiKey: env.SOCIALPANEL24_API_KEY,
    fetchImpl,
    timeoutMs: Number(env.SOCIALPANEL24_TIMEOUT_MS || 15000),
  };
}

function catalogueDeps(env, store, extras) {
  return {
    fetchImpl: extras.fetchImpl,
    now: extras.now,
    cacheGet: typeof store.cacheGet === 'function' ? (key) => store.cacheGet(key) : undefined,
    cacheSet: typeof store.cacheSet === 'function' ? (key, value, ttl) => store.cacheSet(key, value, ttl) : undefined,
  };
}

async function recordAttempt(store, row) {
  if (typeof store.recordExternalAttempt === 'function') {
    await store.recordExternalAttempt(row);
  }
}

function fakeRefillResult(order) {
  const suffix = String(order.id || '0').replace(/[^0-9]/g, '').slice(-8) || '1';
  return { refillId: `8${suffix.padStart(7, '0')}`.slice(0, 8), fake: true };
}

/**
 * Map SocialPanel24 refill_status strings.
 * @param {string} raw
 */
export function mapRefillStatus(raw) {
  const lower = String(raw || '').trim().toLowerCase();
  if (lower === 'completed' || lower === 'complete' || lower === 'success') return 'completed';
  if (lower === 'pending' || lower === 'in progress' || lower === 'processing') return 'pending';
  if (lower === 'rejected' || lower === 'canceled' || lower === 'cancelled') return 'rejected';
  if (lower === 'error' || lower === 'failed') return 'failed';
  return 'pending';
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} order
 * @param {object} [deps]
 * @returns {Promise<{ eligible: boolean, reason: string }>}
 */
export async function refillEligibility(env, store, order, deps = {}) {
  if (!order) return { eligible: false, reason: 'not_found' };
  if (order.payment_status !== 'paid') return { eligible: false, reason: 'not_paid' };
  if (!order.provider_order_id) return { eligible: false, reason: 'missing_provider_order' };
  if (!REFILL_ELIGIBLE_FULFILLMENT.includes(order.fulfillment_status)) {
    return { eligible: false, reason: 'not_refillable_status' };
  }
  if (REFILL_IN_FLIGHT.includes(order.provider_refill_status)) {
    return { eligible: false, reason: 'refill_in_flight' };
  }
  if (order.provider_refill_status === 'unknown') {
    return { eligible: false, reason: 'refill_unknown' };
  }

  if (typeof store.cacheGet === 'function') {
    const kill = await store.cacheGet('ops:provider_kill');
    if (kill && kill.enabled === false) return { eligible: false, reason: 'provider_kill_switch' };
  }

  const gate = providerDispatchGate(env, order);
  if (gate.action !== 'live' && gate.action !== 'fake') {
    return { eligible: false, reason: gate.reason || gate.action };
  }

  try {
    const rows = await getProviderCatalog(env, catalogueDeps(env, store, deps));
    const provider = findProviderService(rows, order.provider_service_id);
    if (!provider) return { eligible: false, reason: 'service_not_found' };
    if (!provider.refill) return { eligible: false, reason: 'refill_not_supported' };
  } catch {
    return { eligible: false, reason: 'provider_unavailable' };
  }

  return { eligible: true, reason: '' };
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} order
 * @param {object} job
 * @param {object} [deps]
 */
export async function requestOrderRefill(env, store, order, job, deps = {}) {
  if (!order) {
    await store.failJob(job.id, { reason: 'missing_order' }, new Date().toISOString(), true);
    return { skipped: true, reason: 'missing_order' };
  }
  if (!order.provider_order_id) {
    await store.skipJob(job.id, { reason: 'missing_provider_order' });
    return { skipped: true, reason: 'missing_provider_order' };
  }
  if (order.provider_refill_status === 'unknown') {
    await store.skipJob(job.id, { reason: 'refill_unknown' });
    return { skipped: true, reason: 'refill_unknown' };
  }
  if (order.provider_refill_id) {
    await store.enqueueJob({
      orderId: null,
      task: 'poll_refill_status',
      dedupeKey: 'refill-poll:batch',
    });
    await store.completeJob(job.id, { reason: 'already_refilling' });
    return { skipped: true, reason: 'already_refilling' };
  }

  if (typeof store.cacheGet === 'function') {
    const kill = await store.cacheGet('ops:provider_kill');
    if (kill && kill.enabled === false) {
      const next = new Date(Date.now() + 5 * 60 * 1000).toISOString();
      await store.failJob(job.id, { reason: 'provider_kill_switch' }, next, false);
      return { skipped: true, deferred: true, reason: 'provider_kill_switch' };
    }
  }

  const gate = providerDispatchGate(env, order);
  if (gate.action === 'skip_test') {
    await store.updateOrder(order.id, { provider_refill_status: 'failed' });
    await store.completeJob(job.id, { reason: gate.reason });
    return { skipped: true, reason: gate.reason };
  }
  if (gate.action === 'defer') {
    const next = new Date(Date.now() + 5 * 60 * 1000).toISOString();
    await store.failJob(job.id, { reason: gate.reason }, next, false);
    return { skipped: true, deferred: true, reason: gate.reason };
  }

  await recordAttempt(store, {
    orderId: order.id,
    jobId: job.id,
    vendor: 'socialpanel24',
    action: 'refill',
    fingerprint: JSON.stringify({ order: order.provider_order_id }),
    attemptedAt: new Date().toISOString(),
  });

  try {
    const result =
      gate.action === 'fake'
        ? fakeRefillResult(order)
        : await requestProviderRefill(providerEnv(env, deps.fetchImpl), order.provider_order_id);
    await store.updateOrder(order.id, {
      provider_refill_id: result.refillId,
      provider_refill_status: 'pending',
      provider_refill_last_status_at: new Date().toISOString(),
    });
    await store.enqueueJob({
      orderId: null,
      task: 'poll_refill_status',
      dedupeKey: 'refill-poll:batch',
    });
    await store.completeJob(job.id, { refillId: result.refillId }, result.refillId);
    return { ok: true, refillId: result.refillId };
  } catch (err) {
    const code = err instanceof SocialPanelError ? err.code : 'TRANSPORT';
    if (code === 'INSUFFICIENT_BALANCE' || code === 'PROVIDER_REJECTED') {
      await store.updateOrder(order.id, { provider_refill_status: 'rejected' });
      await store.enqueueJob({
        orderId: order.id,
        task: 'email_owner_alert',
        dedupeKey: `email:owner:refill_rejected:${order.id}:${job.id}`,
        payload: {
          alert: `Provider rejected the refill: ${err instanceof Error ? err.message : 'rejected'}`,
        },
      });
      await store.completeJob(job.id, { reason: 'provider_rejected', code });
      return { ok: false, reason: 'provider_rejected' };
    }

    await store.updateOrder(order.id, { provider_refill_status: 'unknown' });
    await store.enqueueJob({
      orderId: order.id,
      task: 'email_owner_alert',
      dedupeKey: `email:owner:refill_unknown:${order.id}`,
      payload: {
        alert:
          'Provider refill outcome is unknown. Search SocialPanel24 before requesting another refill. Automatic refill retries are disabled.',
      },
    });
    await store.completeJob(job.id, { reason: 'refill_unknown', code });
    logError('refill unknown', { code });
    return { ok: false, reason: 'refill_unknown' };
  }
}

/**
 * @param {object} env
 * @param {object} store
 * @param {object} [deps]
 */
export async function pollRefillStatuses(env, store, deps = {}) {
  if (typeof store.listRefillPollingOrders !== 'function') return { polled: 0 };
  const orders = await store.listRefillPollingOrders();
  const due = orders.filter(
    (row) => row.provider_refill_id && !REFILL_TERMINAL.includes(row.provider_refill_status)
  );
  if (!due.length) return { polled: 0 };

  let polled = 0;
  for (const order of due) {
    let result;
    try {
      result = await fetchProviderRefillStatuses(providerEnv(env, deps.fetchImpl), [order.provider_refill_id]);
    } catch {
      logError('refill status failed', { size: 1 });
      continue;
    }
    const entry = result[order.provider_refill_id];
    if (!entry) continue;
    polled += 1;
    if (entry.error) {
      await store.updateOrder(order.id, {
        provider_refill_status: 'failed',
        provider_refill_last_status_at: new Date().toISOString(),
      });
      continue;
    }
    const mapped = mapRefillStatus(entry.status);
    await store.updateOrder(order.id, {
      provider_refill_status: mapped,
      provider_refill_last_status_at: new Date().toISOString(),
    });
  }
  return { polled };
}

const SECRET_KEYS = [
  'key',
  'authorization',
  'stripe-signature',
  'x-checkout-token',
  'capabilitytoken',
  'capability_token',
  'token',
  'secret',
  'apikey',
  'api_key',
  'socialpanel24_api_key',
  'resend_api_key',
  'stripe_secret_key',
  'service_role',
];

/**
 * Redact secrets, emails, tokens, and target URLs before logging.
 * @param {unknown} value
 * @returns {unknown}
 */
export function redact(value) {
  if (value == null) return value;
  if (typeof value === 'string') {
    if (value.includes('@') && value.includes('.')) return '[redacted-email]';
    if (/^https?:\/\//i.test(value)) return '[redacted-url]';
    if (value.length > 24 && /^[A-Za-z0-9_\-]+$/.test(value)) return '[redacted]';
    return value;
  }
  if (Array.isArray(value)) return value.map(redact);
  if (typeof value === 'object') {
    /** @type {Record<string, unknown>} */
    const out = {};
    Object.entries(/** @type {Record<string, unknown>} */ (value)).forEach(([key, nested]) => {
      const lower = key.toLowerCase();
      if (SECRET_KEYS.some((name) => lower.includes(name))) {
        out[key] = '[redacted]';
        return;
      }
      if (lower.includes('email') || lower.includes('comment') || lower.includes('payload')) {
        out[key] = '[redacted]';
        return;
      }
      out[key] = redact(nested);
    });
    return out;
  }
  return value;
}

/**
 * @param {string} message
 * @param {unknown} [meta]
 */
export function logInfo(message, meta) {
  if (meta === undefined) {
    console.log(message);
    return;
  }
  console.log(message, redact(meta));
}

/**
 * @param {string} message
 * @param {unknown} [meta]
 */
export function logError(message, meta) {
  if (meta === undefined) {
    console.error(message);
    return;
  }
  console.error(message, redact(meta));
}

/**
 * SocialPanel24 HTTP adapter. Server-only. Credentials never go in URLs or logs.
 *
 * Endpoint is fixed: POST https://socialpanel24.com/api/v2
 * Body: application/x-www-form-urlencoded via URLSearchParams.
 */

export const SOCIALPANEL24_URL = 'https://socialpanel24.com/api/v2';

const ALLOWED_ACTIONS = new Set(['services', 'add', 'status', 'balance', 'refill', 'refill_status']);

export class SocialPanelError extends Error {
  /**
   * @param {string} message
   * @param {{ code: string, retryable?: boolean, httpStatus?: number, providerError?: string }} info
   */
  constructor(message, info) {
    super(message);
    this.name = 'SocialPanelError';
    this.code = info.code;
    this.retryable = Boolean(info.retryable);
    this.httpStatus = info.httpStatus;
    this.providerError = info.providerError;
  }
}

/**
 * @param {string} raw
 * @returns {string}
 */
function classifyProviderError(raw) {
  const text = String(raw || '').toLowerCase();
  if (!text) return 'PROVIDER_REJECTED';
  if (text.includes('balance') || text.includes('funds') || text.includes('not enough')) {
    return 'INSUFFICIENT_BALANCE';
  }
  return 'PROVIDER_REJECTED';
}

/**
 * @param {unknown} value
 * @returns {string|null}
 */
export function parseProviderOrderId(value) {
  if (value == null || value === '') return null;
  const text = String(value).trim();
  if (!/^\d+$/.test(text)) return null;
  return text;
}

/**
 * Parse SocialPanel numeric strings safely.
 * @param {unknown} value
 * @returns {number|null}
 */
export function parseProviderNumber(value) {
  if (value == null || value === '') return null;
  const num = Number(String(value).trim());
  return Number.isFinite(num) ? num : null;
}

/**
 * POST to SocialPanel24. TLS verification stays on. Redirects are rejected.
 *
 * @param {{
 *   apiKey: string,
 *   fetchImpl?: typeof fetch,
 *   timeoutMs?: number,
 *   now?: () => number
 * }} env
 * @param {string} action
 * @param {Record<string, string>} [fields]
 */
export async function socialPanelRequest(env, action, fields = {}) {
  if (!ALLOWED_ACTIONS.has(action)) {
    throw new SocialPanelError(`Action is not allowlisted: ${action}`, { code: 'INVALID_ACTION' });
  }
  const key = String(env.apiKey || '');
  if (!key) {
    throw new SocialPanelError('SocialPanel24 API key is not configured', { code: 'CONFIG' });
  }

  const body = new URLSearchParams();
  body.set('key', key);
  body.set('action', action);
  Object.entries(fields).forEach(([name, value]) => {
    if (name === 'key' || name === 'action') return;
    if (value == null || value === '') return;
    body.set(name, String(value));
  });

  const controller = new AbortController();
  const timeoutMs = Number(env.timeoutMs) > 0 ? Number(env.timeoutMs) : 15000;
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  const fetchImpl = env.fetchImpl || fetch;

  /** @type {Response} */
  let response;
  try {
    response = await fetchImpl(SOCIALPANEL24_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body,
      redirect: 'error',
      signal: controller.signal,
    });
  } catch (err) {
    const aborted = Boolean(err && /** @type {{ name?: string }} */ (err).name === 'AbortError');
    throw new SocialPanelError(aborted ? 'SocialPanel24 request timed out' : 'SocialPanel24 transport failed', {
      code: aborted ? 'TIMEOUT' : 'TRANSPORT',
      retryable: true,
    });
  } finally {
    clearTimeout(timer);
  }

  const raw = await response.text();
  let json;
  try {
    json = raw ? JSON.parse(raw) : null;
  } catch {
    throw new SocialPanelError('SocialPanel24 returned malformed JSON', {
      code: 'MALFORMED',
      retryable: true,
      httpStatus: response.status,
    });
  }

  if (!response.ok) {
    throw new SocialPanelError(`SocialPanel24 HTTP ${response.status}`, {
      code: response.status >= 500 ? 'TRANSPORT' : 'HTTP_ERROR',
      retryable: response.status >= 500,
      httpStatus: response.status,
    });
  }

  if (json && typeof json === 'object' && json.error) {
    const providerError = String(json.error);
    const code = classifyProviderError(providerError);
    throw new SocialPanelError(providerError, {
      code,
      retryable: false,
      providerError,
    });
  }

  return json;
}

/**
 * @param {any} env
 */
export async function fetchProviderServices(env) {
  const data = await socialPanelRequest(env, 'services');
  return Array.isArray(data) ? data : [];
}

/**
 * @param {any} env
 * @param {Record<string, string>} addFields
 */
export async function addProviderOrder(env, addFields) {
  const json = await socialPanelRequest(env, 'add', addFields);
  const orderId = parseProviderOrderId(json?.order ?? json?.id);
  if (!orderId) {
    throw new SocialPanelError('SocialPanel24 accepted the HTTP request but returned no order id', {
      code: 'MALFORMED',
      retryable: false,
    });
  }
  return { orderId, raw: json };
}

/**
 * @param {any} env
 * @param {string[]} orderIds
 */
export async function fetchProviderStatuses(env, orderIds) {
  const ids = [...new Set(orderIds.map((id) => String(id).trim()).filter(Boolean))];
  if (!ids.length) return {};
  if (ids.length > 100) {
    throw new SocialPanelError('Status batch exceeds 100 ids', { code: 'INVALID_ACTION' });
  }
  if (ids.length === 1) {
    const json = await socialPanelRequest(env, 'status', { order: ids[0] });
    return { [ids[0]]: json };
  }
  const json = await socialPanelRequest(env, 'status', { orders: ids.join(',') });
  return json && typeof json === 'object' ? json : {};
}

/**
 * @param {any} env
 */
export async function fetchProviderBalance(env) {
  return socialPanelRequest(env, 'balance');
}

/**
 * @param {any} env
 * @param {string} providerOrderId
 */
export async function requestProviderRefill(env, providerOrderId) {
  const orderId = parseProviderOrderId(providerOrderId);
  if (!orderId) {
    throw new SocialPanelError('Refill requires a numeric provider order id', { code: 'INVALID_ACTION' });
  }
  const json = await socialPanelRequest(env, 'refill', { order: orderId });
  const refillId = parseProviderOrderId(json?.refill ?? json?.order ?? json?.id);
  if (!refillId) {
    throw new SocialPanelError('SocialPanel24 accepted the HTTP request but returned no refill id', {
      code: 'MALFORMED',
      retryable: false,
    });
  }
  return { refillId, raw: json };
}

/**
 * Single-id refill_status. Mass `refills=` is not used — the public API shape for
 * batches is not evidenced in this repo.
 * @param {any} env
 * @param {string[]} refillIds
 */
export async function fetchProviderRefillStatuses(env, refillIds) {
  const ids = [...new Set(refillIds.map((id) => String(id).trim()).filter(Boolean))];
  if (!ids.length) return {};
  /** @type {Record<string, any>} */
  const out = {};
  for (const id of ids) {
    const json = await socialPanelRequest(env, 'refill_status', { refill: id });
    out[id] = json && typeof json === 'object' ? json : {};
  }
  return out;
}

/**
 * Normalize a provider service row. Rates stay decimal; currency is not inferred.
 * @param {Record<string, unknown>} row
 */
export function normalizeProviderService(row) {
  const service = String(row.service ?? row.id ?? '').trim();
  return {
    service,
    name: String(row.name ?? '').trim(),
    type: String(row.type ?? '').trim(),
    category: String(row.category ?? '').trim(),
    rate: String(row.rate ?? '').trim(),
    min: parseProviderNumber(row.min),
    max: parseProviderNumber(row.max),
    refill: Boolean(row.refill),
    cancel: Boolean(row.cancel),
    raw: row,
  };
}

/**
 * Payment and fulfilment state machines. Unknown remains unknown.
 */

export const PAYMENT_STATES = Object.freeze(['pending', 'paid', 'failed', 'expired', 'cancelled']);
export const FULFILLMENT_STATES = Object.freeze([
  'not_started',
  'dispatching',
  'submitted',
  'in_progress',
  'completed',
  'partial',
  'failed',
  'cancelled',
  'submission_unknown',
  'blocked_balance',
  'skipped_test_mode',
  'deferred',
  'review',
]);

const PAID_LOCK = new Set(['paid']);

/**
 * Late events must not downgrade a paid order.
 * @param {string} current
 * @param {string} next
 * @returns {string}
 */
export function transitionPayment(current, next) {
  if (PAID_LOCK.has(current)) return current;
  if (next === 'paid') return 'paid';
  if (PAYMENT_STATES.includes(next)) return next;
  return current || 'pending';
}

/**
 * Map SocialPanel24 status strings. Unfamiliar values stay in review.
 * @param {string} raw
 */
export function mapProviderStatus(raw) {
  const value = String(raw || '').trim();
  const lower = value.toLowerCase();
  if (lower === 'completed' || lower === 'complete') return 'completed';
  if (lower === 'in progress' || lower === 'processing' || lower === 'pending') return 'in_progress';
  if (lower === 'partial') return 'partial';
  if (lower === 'canceled' || lower === 'cancelled') return 'cancelled';
  if (lower === 'refunded') return 'cancelled';
  if (lower === 'error' || lower === 'failed' || lower === 'rejected') return 'failed';
  return 'review';
}

/**
 * UI projection from stored facts. Payment success does not imply fulfilment
 * or email delivery.
 * @param {{ paymentStatus: string, fulfillmentStatus: string }} order
 */
export function publicUiState(order) {
  const payment = order.paymentStatus;
  const fulfillment = order.fulfillmentStatus;
  if (payment === 'pending') return 'awaiting_confirmation';
  if (payment === 'failed') return 'failed';
  if (payment === 'expired' || payment === 'cancelled') return 'expired';
  if (payment !== 'paid') return 'unknown';
  if (fulfillment === 'completed') return 'completed';
  if (fulfillment === 'failed' || fulfillment === 'blocked_balance') return 'failed';
  if (fulfillment === 'cancelled' || fulfillment === 'partial') return 'failed';
  if (fulfillment === 'in_progress' || fulfillment === 'submitted' || fulfillment === 'dispatching') {
    return 'processing';
  }
  if (fulfillment === 'not_started' || fulfillment === 'skipped_test_mode' || fulfillment === 'deferred') {
    return 'payment_received';
  }
  if (fulfillment === 'submission_unknown' || fulfillment === 'review') return 'processing';
  return 'unknown';
}

/**
 * @param {string} rawId
 * @param {string} [prefix='LD-']
 */
export function formatDisplayId(rawId, prefix = 'LD-') {
  const short = String(rawId || '')
    .replace(/-/g, '')
    .slice(-6)
    .toUpperCase();
  return short ? `${prefix}${short}` : '';
}

/**
 * Join retail catalogue with SocialPanel24 services. Request-path cache TTL is
 * 5 minutes; stale cache (up to 1 hour) is served if the provider is down.
 * `refreshCatalogue` force-pulls SocialPanel24 and rewrites catalogue_cache
 * (scheduled daily by pg_cron).
 */

import { loadRetailCatalogue } from './retail-adapter.js';
import { fetchProviderServices, normalizeProviderService } from './socialpanel24.js';
import { findProviderService, quoteService, toPublicService } from './pricing.js';
import { getProviderType, isSupportedProviderType } from './provider-types.js';
import { parseInputList } from './inputs.js';

export const CATALOGUE_TTL_MS = 5 * 60 * 1000;
export const CATALOGUE_STALE_MS = 60 * 60 * 1000;
export const PROVIDER_TIMEOUT_MS = 8000;

const memory = {
  public: /** @type {{ expires: number, staleUntil: number, payload: object }|null} */ (null),
  provider: /** @type {{ expires: number, services: any[] }|null} */ (null),
};

/**
 * @param {object} env
 */
export function pricingEnv(env) {
  return {
    retailCurrency: String(env.RETAIL_CURRENCY || 'USD').toUpperCase(),
    providerCurrency: String(env.PROVIDER_CURRENCY || env.RETAIL_CURRENCY || 'USD').toUpperCase(),
    fxProviderToRetail: Number(env.FX_PROVIDER_TO_RETAIL || 1),
    defaultMarkup: Number(env.MARKUP_MULTIPLIER || 2),
  };
}

/**
 * @param {object} env
 * @param {object} deps
 */
export async function getProviderCatalog(env, deps = {}) {
  const now = deps.now ? deps.now() : Date.now();
  const force = Boolean(deps.forceRefresh);
  if (!force && memory.provider && memory.provider.expires > now) return memory.provider.services;
  if (!force && deps.cacheGet) {
    const cached = await deps.cacheGet('sp24:services');
    if (cached && Array.isArray(cached.services) && cached.expires > now) {
      memory.provider = { expires: cached.expires, services: cached.services };
      return cached.services;
    }
  }

  const timeoutMs = Number(
    env.SOCIALPANEL24_TIMEOUT_MS || (force ? 20000 : PROVIDER_TIMEOUT_MS)
  );
  const services = await fetchProviderServices({
    apiKey: env.SOCIALPANEL24_API_KEY,
    fetchImpl: deps.fetchImpl,
    timeoutMs,
  });
  const normalized = services.map((row) => normalizeProviderService(row));
  const expires = now + CATALOGUE_TTL_MS;
  memory.provider = { expires, services: normalized };
  if (deps.cacheSet && normalized.length) {
    await deps.cacheSet('sp24:services', { expires, services: normalized }, CATALOGUE_STALE_MS);
  }
  return normalized;
}

/**
 * @param {import('./retail-catalogue.js').RetailService} retail
 * @param {ReturnType<typeof normalizeProviderService>|null} provider
 * @param {ReturnType<typeof pricingEnv>} money
 */
export function joinService(retail, provider, money) {
  const label = `${retail.platformLabel} ${retail.service}`.trim();
  const typeHandler = provider ? getProviderType(provider.type) : null;
  const supported = Boolean(provider && typeHandler && typeHandler.enabled);
  const mapped = Boolean(retail.socialpanelId && provider);
  const enabled = Boolean(retail.visible && mapped && supported);

  const probeQty = retail.quantityDefault || provider?.min || 1;
  const quote = enabled
    ? quoteService({
        retail,
        provider,
        quantity: probeQty,
        inputs: {},
        retailCurrency: money.retailCurrency,
        providerCurrency: money.providerCurrency,
        fxProviderToRetail: money.fxProviderToRetail,
      })
    : { ok: false };

  const inputs = retail.inputs.length
    ? retail.inputs
    : typeHandler
      ? typeHandler.storefrontInputs
      : parseInputList('');

  return {
    id: retail.id,
    platform: retail.platform,
    platformLabel: retail.platformLabel,
    type: provider?.type || '',
    service: retail.service,
    label,
    description: retail.description,
    enabled,
    purchasable: Boolean(enabled && quote.ok),
    inputs,
    quantityMin: quote.ok ? quote.quantityMin : provider?.min ?? null,
    quantityMax: quote.ok ? quote.quantityMax : provider?.max ?? null,
    quantityStep: retail.quantityStep,
    quantityDefault: retail.quantityDefault,
    currency: money.retailCurrency,
    retailRateMinor: quote.ok ? quote.retailRateMinor : null,
    rateUnit: retail.rateUnit,
    quantityMode:
      typeHandler?.quantityMode ||
      (retail.inputs.includes('comments') ? 'from_comments' : 'required'),
    socialpanelId: retail.socialpanelId,
    providerServiceId: provider?.service || '',
    providerType: provider?.type || '',
    providerMin: provider?.min ?? null,
    providerMax: provider?.max ?? null,
    providerRate: provider?.rate || '',
    refill: Boolean(provider?.refill),
    cancel: Boolean(provider?.cancel),
    dripEnabled: retail.dripEnabled,
    markupMultiplier: retail.markupMultiplier,
    packagePriceMinor: retail.packagePriceMinor,
    minContributionMinor: retail.minContributionMinor,
    disableReason: enabled
      ? ''
      : !retail.visible
        ? 'hidden'
        : !retail.socialpanelId
          ? 'unmapped'
          : !provider
            ? 'missing'
            : !isSupportedProviderType(provider.type)
              ? 'unsupported_type'
              : 'unavailable',
  };
}

/**
 * @param {object} env
 * @param {object} [deps]
 */
export async function buildCatalogue(env, deps = {}) {
  const money = pricingEnv(env);
  const retail = await loadRetailCatalogue({
    listProducts: deps.listProducts,
    sheetUrl: env.RETAIL_CATALOGUE_URL,
    socialpanelIds: env.RETAIL_SOCIALPANEL_IDS,
    fetchImpl: deps.fetchImpl,
    timeoutMs: Number(env.CATALOGUE_TIMEOUT_MS || 8000),
    defaultCurrency: money.retailCurrency,
    defaultMarkup: money.defaultMarkup,
  });

  let providerRows = [];
  let providerError = '';
  try {
    providerRows = await getProviderCatalog(env, deps);
  } catch (err) {
    providerError = err instanceof Error ? err.message : 'provider_unavailable';
    if (deps.cacheGet) {
      const stale = await deps.cacheGet('sp24:services');
      if (stale && Array.isArray(stale.services)) providerRows = stale.services;
    } else if (memory.provider?.services) {
      providerRows = memory.provider.services;
    }
  }

  const internals = retail.map((row) => {
    const provider = findProviderService(providerRows, row.socialpanelId);
    return joinService(row, provider, money);
  });

  return {
    internals,
    publicServices: internals
      .filter((row) => row.disableReason !== 'hidden')
      .map(toPublicServiceFromInternal),
    providerError,
    money,
  };
}

/**
 * @param {ReturnType<typeof joinService>} internal
 */
function toPublicServiceFromInternal(internal) {
  return toPublicService({
    ...internal,
    enabled: internal.enabled,
    purchasable: internal.purchasable,
  });
}

/**
 * Cached public catalogue.
 * @param {object} env
 * @param {object} [deps]
 */
async function applyCataloguePause(payload, deps) {
  if (typeof deps.cacheGet !== 'function') return payload;
  const paused = await deps.cacheGet('ops:catalogue_paused');
  if (!paused || paused.paused !== true) return payload;
  const data = Array.isArray(payload.data)
    ? payload.data.map((row) => ({ ...row, purchasable: false, enabled: false }))
    : payload.data;
  return { ...payload, data, paused: true };
}

export async function getPublicCatalogue(env, deps = {}) {
  const now = deps.now ? deps.now() : Date.now();
  if (memory.public && memory.public.expires > now) {
    return applyCataloguePause({ ...memory.public.payload, cache: 'memory' }, deps);
  }
  if (deps.cacheGet) {
    const cached = await deps.cacheGet('catalogue:public');
    if (cached && cached.expires > now) {
      memory.public = cached;
      return applyCataloguePause({ ...cached.payload, cache: 'store' }, deps);
    }
  }

  try {
    const built = await buildCatalogue(env, deps);
    const payload = {
      ok: true,
      data: built.publicServices,
      generatedAt: new Date(now).toISOString(),
      ttlSeconds: Math.round(CATALOGUE_TTL_MS / 1000),
    };
    const providerOk = !built.providerError;
    const ttl = providerOk ? CATALOGUE_TTL_MS : 30 * 1000;
    const entry = {
      expires: now + ttl,
      staleUntil: providerOk ? now + CATALOGUE_STALE_MS : now + ttl,
      payload,
    };
    memory.public = entry;
    if (deps.cacheSet && providerOk) await deps.cacheSet('catalogue:public', entry, CATALOGUE_STALE_MS);
    return applyCataloguePause({ ...payload, cache: 'fresh' }, deps);
  } catch (err) {
    if (memory.public && memory.public.staleUntil > now) {
      return applyCataloguePause({ ...memory.public.payload, cache: 'stale', warning: 'refresh_failed' }, deps);
    }
    if (deps.cacheGet) {
      const stale = await deps.cacheGet('catalogue:public');
      if (stale && stale.staleUntil > now) {
        return applyCataloguePause({ ...stale.payload, cache: 'stale', warning: 'refresh_failed' }, deps);
      }
    }
    throw err;
  }
}

/**
 * @param {object} env
 * @param {string} serviceId
 * @param {object} [deps]
 */
export async function getInternalService(env, serviceId, deps = {}) {
  const built = await buildCatalogue(env, deps);
  return built.internals.find((row) => row.id === serviceId) || null;
}

export function clearCatalogueMemory() {
  memory.public = null;
  memory.provider = null;
}

/**
 * Force-fetch SocialPanel24 services and rewrite catalogue_cache.
 * Does not insert storefront products. Mapped `public.products` rows stay
 * curated; missing or empty provider lists leave the previous cache in place.
 *
 * @param {object} env
 * @param {object} [deps]
 */
export async function refreshCatalogue(env, deps = {}) {
  const now = deps.now ? deps.now() : Date.now();
  clearCatalogueMemory();

  let providerRows = [];
  try {
    providerRows = await getProviderCatalog(env, { ...deps, forceRefresh: true });
  } catch (err) {
    return {
      ok: false,
      refreshed: false,
      providerError: err instanceof Error ? err.message : 'provider_unavailable',
      providerCount: 0,
      cacheKeys: [],
      visible: 0,
      purchasable: 0,
      unmapped: 0,
      missing: 0,
      products: [],
    };
  }

  if (!providerRows.length) {
    return {
      ok: false,
      refreshed: false,
      providerError: 'empty_provider_catalogue',
      providerCount: 0,
      cacheKeys: [],
      visible: 0,
      purchasable: 0,
      unmapped: 0,
      missing: 0,
      products: [],
    };
  }

  const built = await buildCatalogue(env, deps);
  const payload = {
    ok: true,
    data: built.publicServices,
    generatedAt: new Date(now).toISOString(),
    ttlSeconds: Math.round(CATALOGUE_TTL_MS / 1000),
  };
  const entry = {
    expires: now + CATALOGUE_TTL_MS,
    staleUntil: now + CATALOGUE_STALE_MS,
    payload,
  };
  memory.public = entry;

  /** @type {string[]} */
  const cacheKeys = [];
  if (deps.cacheSet) {
    await deps.cacheSet('sp24:services', { expires: now + CATALOGUE_TTL_MS, services: providerRows }, CATALOGUE_STALE_MS);
    await deps.cacheSet('catalogue:public', entry, CATALOGUE_STALE_MS);
    cacheKeys.push('sp24:services', 'catalogue:public');
  }

  const products = built.internals.map((row) => ({
    id: row.id,
    label: row.label,
    purchasable: Boolean(row.purchasable),
    disableReason: row.disableReason || '',
  }));

  return {
    ok: true,
    refreshed: true,
    providerError: built.providerError || '',
    providerCount: providerRows.length,
    cacheKeys,
    visible: products.filter((row) => row.disableReason !== 'hidden').length,
    purchasable: products.filter((row) => row.purchasable).length,
    unmapped: products.filter((row) => row.disableReason === 'unmapped').length,
    missing: products.filter((row) => row.disableReason === 'missing').length,
    products,
  };
}

/**
 * Server-side quoting. Provider cost stays private. Retail currency, rate unit,
 * markup, and FX are explicit configuration — never inferred from PHP samples.
 */

import { applyMarkup, convertMinor, parseDecimalToMinor, quoteTotalMinor, quoteVersion } from './money.js';
import { billableQuantityForType, getProviderType } from './provider-types.js';
import { normalizeProviderService } from './socialpanel24.js';

/**
 * Raise the selling price when contribution would not cover an estimated Stripe
 * fee plus a per-service floor. Sub-50¢ SKUs (comment micros) keep markup-only
 * pricing because the 30¢ fixed fee would dominate them.
 * @param {number} amountMinor
 * @param {number} expectedProviderCostMinor
 * @param {number} [minContributionMinor]
 */
export function applyContributionFloor(amountMinor, expectedProviderCostMinor, minContributionMinor = 0) {
  const amount = Number(amountMinor);
  const cost = Number(expectedProviderCostMinor);
  const minC = Number.isInteger(minContributionMinor) && minContributionMinor > 0 ? minContributionMinor : 0;
  if (!Number.isInteger(amount) || amount < 50 || !Number.isInteger(cost) || cost < 0) return amount;
  const stripeFeeFloor = Math.ceil(amount * 0.029) + 30;
  const needed = cost + minC + stripeFeeFloor;
  return amount < needed ? needed : amount;
}

/**
 * @param {Array<Record<string, unknown>>} catalog
 * @param {string} socialpanelId
 */
export function findProviderService(catalog, socialpanelId) {
  const id = String(socialpanelId ?? '').trim();
  if (!id) return null;
  const row = catalog.find((entry) => String(entry.service ?? entry.id ?? '') === id);
  return row ? normalizeProviderService(row) : null;
}

/**
 * @param {{
 *   retail: import('./retail-catalogue.js').RetailService,
 *   provider: ReturnType<typeof normalizeProviderService>,
 *   quantity: number,
 *   inputs?: Record<string, string>,
 *   retailCurrency: string,
 *   providerCurrency: string,
 *   fxProviderToRetail: number,
 *   dripRuns?: number
 * }} args
 */
export function quoteService(args) {
  const { retail, provider } = args;
  if (!retail?.visible) {
    return { ok: false, error: 'That service is not available.', code: 'unavailable' };
  }
  if (!retail.socialpanelId) {
    return { ok: false, error: 'That service cannot be purchased right now.', code: 'unmapped' };
  }
  if (!provider) {
    return { ok: false, error: 'That service cannot be purchased right now.', code: 'unmapped' };
  }

  const typeHandler = getProviderType(provider.type);
  if (!typeHandler || !typeHandler.enabled) {
    return { ok: false, error: 'That service type is not supported.', code: 'unsupported_type' };
  }

  const min = Number.isFinite(provider.min) ? provider.min : 1;
  const max = Number.isFinite(provider.max) ? provider.max : 10_000_000;

  let billable;
  try {
    if (typeHandler.quantityMode === 'from_comments' && !String(args.inputs?.comments || '').trim()) {
      billable = args.quantity || 1;
    } else {
      billable = billableQuantityForType(provider.type, {
        platform: retail.platform,
        quantity: args.quantity,
        inputs: args.inputs || {},
      });
    }
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : 'Invalid quantity.', code: 'quantity' };
  }

  if (typeHandler.quantityMode !== 'package' && typeHandler.quantityMode !== 'omit') {
    if (billable < min) {
      return { ok: false, error: `Quantity must be at least ${min}.`, code: 'quantity' };
    }
    if (billable > max) {
      return { ok: false, error: `Quantity cannot exceed ${max}.`, code: 'quantity' };
    }
    const step = Number.isInteger(retail.quantityStep) && retail.quantityStep > 1 ? retail.quantityStep : 1;
    if (step > 1 && billable % step !== 0) {
      return { ok: false, error: `Quantity must increase in steps of ${step}.`, code: 'quantity' };
    }
  }

  const runs = args.dripRuns && args.dripRuns > 1 ? args.dripRuns : 1;
  const pricedQuantity = typeHandler.quantityMode === 'package' ? 1 : billable * runs;

  const providerMinor = parseDecimalToMinor(provider.rate, args.providerCurrency);
  if (providerMinor == null) {
    return { ok: false, error: 'This service cannot be priced right now.', code: 'unpriced' };
  }

  let converted;
  try {
    converted = convertMinor(providerMinor, args.providerCurrency, args.retailCurrency, args.fxProviderToRetail);
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : 'Currency conversion is not configured.', code: 'fx' };
  }

  const markup = Number(retail.markupMultiplier);
  let retailRateMinor;
  try {
    retailRateMinor = applyMarkup(converted, markup);
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : 'Invalid markup.', code: 'markup' };
  }

  const rateUnit = retail.rateUnit;
  let amountMinor;
  try {
    amountMinor = quoteTotalMinor({
      rateMinor: retailRateMinor,
      quantity: pricedQuantity,
      rateUnit,
      packageMinor: retail.packagePriceMinor ?? retailRateMinor,
    });
  } catch (err) {
    return { ok: false, error: err instanceof Error ? err.message : 'Could not calculate the total.', code: 'quote' };
  }

  if (amountMinor < 1) {
    return { ok: false, error: 'This service cannot be priced right now.', code: 'unpriced' };
  }

  const expectedProviderCostMinor = quoteTotalMinor({
    rateMinor: converted,
    quantity: pricedQuantity,
    rateUnit,
    packageMinor: converted,
  });
  const minContributionMinor = Number.isInteger(retail.minContributionMinor)
    ? retail.minContributionMinor
    : Number.isInteger(args.minContributionMinor)
      ? args.minContributionMinor
      : 0;
  amountMinor = applyContributionFloor(amountMinor, expectedProviderCostMinor, minContributionMinor);
  const expectedContributionMinor = amountMinor - expectedProviderCostMinor;

  const quote = {
    ok: true,
    serviceId: retail.id,
    quantity: args.quantity,
    billableQuantity: billable,
    dripRuns: runs,
    pricedQuantity,
    amountMinor,
    currency: args.retailCurrency,
    rateUnit,
    retailRateMinor,
    quantityMin: min,
    quantityMax: max,
    quantityStep: retail.quantityStep,
    quantityDefault: retail.quantityDefault,
    markup,
    expectedProviderCostMinor,
    expectedContributionMinor,
    minContributionMinor,
    fxProviderToRetail: args.fxProviderToRetail,
    providerType: provider.type,
    providerServiceId: provider.service,
  };
  quote.quoteVersion = quoteVersion(quote);
  return quote;
}

/**
 * Public catalogue fields only — no provider ids, rates, or costs.
 * @param {object} internal
 */
export function toPublicService(internal) {
  return {
    id: internal.id,
    platform: internal.platform,
    platformLabel: internal.platformLabel,
    type: internal.type,
    service: internal.service,
    label: internal.label,
    description: internal.description,
    enabled: internal.enabled,
    purchasable: internal.purchasable,
    inputs: internal.inputs,
    quantityMin: internal.quantityMin,
    quantityMax: internal.quantityMax,
    quantityStep: internal.quantityStep,
    quantityDefault: internal.quantityDefault,
    currency: internal.currency,
    retailRateMinor: internal.retailRateMinor,
    rateUnit: internal.rateUnit,
    quantityMode: internal.quantityMode,
  };
}

/**
 * Storefront sheet-row adapter. Accepts `{ ok: true, data: [...] }` rows with
 * ID/Platform/Service/Description/Price/Inputs/Visible/socialpanelId and lowercase aliases.
 */

import { parseInputList } from './inputs.js';
import { RETAIL_CATALOGUE } from './retail-catalogue.js';

/**
 * @param {unknown} value
 * @returns {boolean}
 */
function isVisible(value) {
  if (value === true || value === 1) return true;
  if (value === false || value === 0 || value == null) return false;
  const normalized = String(value).trim().toLowerCase();
  return normalized === 'true' || normalized === '1' || normalized === 'yes';
}

/**
 * @param {string} platformLabel
 */
function toPlatformSlug(platformLabel) {
  return String(platformLabel ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '');
}

/**
 * @param {unknown} value
 * @returns {import('./retail-catalogue.js').RateUnit}
 */
function parseRateUnit(value) {
  const unit = String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[\s-]+/g, '_');
  if (unit === 'per_1000' || unit === 'per1000' || unit === 'per_1k') return 'per_1000';
  if (unit === 'per_unit' || unit === 'per_item') return 'per_unit';
  if (unit === 'package') return 'package';
  if (unit === 'per_comment' || unit === 'per_comments') return 'per_comment';
  return '';
}

/**
 * Normalize a sheet-like row onto the retail service model.
 * Invalid entries return null.
 * @param {Record<string, unknown>} row
 * @param {{ defaultCurrency?: string, defaultMarkup?: number }} [defaults]
 * @returns {import('./retail-catalogue.js').RetailService|null}
 */
export function normalizeRetailRow(row, defaults = {}) {
  const platformLabel = String(row.Platform ?? row.platform ?? row.platformLabel ?? '').trim();
  const platform = toPlatformSlug(platformLabel);
  const service = String(row.Service ?? row.service ?? '').trim();
  const id = String(row.ID ?? row.id ?? row.serviceId ?? '').trim();
  if (!id || !platform || !service) return null;

  const socialpanelId = String(
    row.socialpanelId ?? row.SocialPanelId ?? row.socialPanelId ?? row.SocialpanelId ?? ''
  ).trim();

  const rateUnit =
    parseRateUnit(row.rateUnit ?? row.RateUnit ?? row.rate_unit) ||
    (parseInputList(row.Inputs ?? row.inputs).includes('comments') ? 'per_comment' : 'per_1000');

  const markup = Number(row.markupMultiplier ?? row.markup ?? defaults.defaultMarkup ?? 2);
  const step = Number(row.quantityStep ?? row.QuantityStep ?? 1);
  const qtyDefaultRaw = row.quantityDefault ?? row.QuantityDefault;
  const qtyDefault =
    qtyDefaultRaw == null || qtyDefaultRaw === '' ? (rateUnit === 'per_comment' ? null : 1000) : Number(qtyDefaultRaw);

  if (!Number.isFinite(markup) || markup < 1) return null;
  if (!Number.isInteger(step) || step < 1) return null;

  return {
    id,
    platform,
    platformLabel: platformLabel || platform,
    service,
    description: String(row.Description ?? row.description ?? '').trim(),
    inputs: parseInputList(row.Inputs ?? row.inputs ?? ''),
    visible: isVisible(row.Visible ?? row.visible),
    socialpanelId,
    rateUnit,
    retailCurrency: String(row.retailCurrency ?? row.currency ?? defaults.defaultCurrency ?? 'USD')
      .trim()
      .toUpperCase(),
    markupMultiplier: markup,
    quantityStep: step,
    quantityDefault: Number.isInteger(qtyDefault) ? qtyDefault : null,
    packagePriceMinor:
      row.packagePriceMinor == null || row.packagePriceMinor === ''
        ? null
        : Math.round(Number(row.packagePriceMinor)),
    dripEnabled: isVisible(row.dripEnabled ?? row.drip),
    minContributionMinor: Number.isInteger(Number(row.minContributionMinor ?? row.min_contribution_minor))
      ? Number(row.minContributionMinor ?? row.min_contribution_minor)
      : undefined,
  };
}

/**
 * @param {unknown} payload
 * @param {{ defaultCurrency?: string, defaultMarkup?: number }} [defaults]
 */
export function adaptSheetCatalogue(payload, defaults = {}) {
  let rows = [];
  if (Array.isArray(payload)) rows = payload;
  else if (payload && typeof payload === 'object') {
    const body = /** @type {{ ok?: boolean, data?: unknown, services?: unknown }} */ (payload);
    if (body.ok === false) return [];
    if (Array.isArray(body.data)) rows = body.data;
    else if (Array.isArray(body.services)) rows = body.services;
  }
  return rows
    .map((row) => (row && typeof row === 'object' ? normalizeRetailRow(/** @type {any} */ (row), defaults) : null))
    .filter(Boolean);
}

/**
 * Map a `public.products` row onto the retail service model.
 * @param {Record<string, unknown>} row
 * @param {{ defaultCurrency?: string, defaultMarkup?: number }} [defaults]
 * @returns {import('./retail-catalogue.js').RetailService|null}
 */
export function productRowToRetail(row, defaults = {}) {
  if (!row || typeof row !== 'object') return null;
  return normalizeRetailRow(
    {
      id: row.id,
      Platform: row.platform_label || row.platformLabel || row.platform,
      Service: row.service,
      Description: row.description,
      Inputs: row.inputs,
      Visible: row.visible,
      socialpanelId: row.socialpanel_id ?? row.socialpanelId,
      rateUnit: row.rate_unit ?? row.rateUnit,
      retailCurrency: row.retail_currency ?? row.retailCurrency,
      markupMultiplier: row.markup_multiplier ?? row.markupMultiplier,
      quantityStep: row.quantity_step ?? row.quantityStep,
      quantityDefault: row.quantity_default ?? row.quantityDefault,
      packagePriceMinor: row.package_price_minor ?? row.packagePriceMinor,
      dripEnabled: row.drip_enabled ?? row.dripEnabled,
      minContributionMinor: row.min_contribution_minor ?? row.minContributionMinor,
    },
    defaults
  );
}

/**
 * Overlay provider ids from `RETAIL_SOCIALPANEL_IDS` JSON (`{"01":"123"}`)
 * without replacing the bundled retail rows.
 * @param {import('./retail-catalogue.js').RetailService[]} rows
 * @param {string|Record<string, unknown>|undefined} raw
 */
export function applySocialpanelIdOverlay(rows, raw) {
  if (raw == null || raw === '') return rows;
  let map = raw;
  if (typeof raw === 'string') {
    try {
      map = JSON.parse(raw);
    } catch {
      return rows;
    }
  }
  if (!map || typeof map !== 'object' || Array.isArray(map)) return rows;
  return rows.map((row) => {
    const next = /** @type {Record<string, unknown>} */ (map)[row.id];
    if (next == null || String(next).trim() === '') return row;
    return { ...row, socialpanelId: String(next).trim() };
  });
}

/**
 * Load retail services: `products` table, optional remote sheet JSON, else bundled catalogue.
 * @param {{
 *   listProducts?: () => Promise<unknown[]>,
 *   sheetUrl?: string,
 *   socialpanelIds?: string|Record<string, unknown>,
 *   fetchImpl?: typeof fetch,
 *   timeoutMs?: number,
 *   defaultCurrency?: string,
 *   defaultMarkup?: number
 * }} options
 */
export async function loadRetailCatalogue(options = {}) {
  let rows;
  if (typeof options.listProducts === 'function') {
    try {
      const products = await options.listProducts();
      const adapted = Array.isArray(products)
        ? products.map((row) => productRowToRetail(/** @type {any} */ (row), options)).filter(Boolean)
        : [];
      if (adapted.length) rows = adapted;
    } catch {
      rows = undefined;
    }
  }
  if (!rows && options.sheetUrl) {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), options.timeoutMs || 8000);
    try {
      const response = await (options.fetchImpl || fetch)(options.sheetUrl, { signal: controller.signal });
      if (!response.ok) throw new Error(`Retail catalogue HTTP ${response.status}`);
      const json = await response.json();
      const adapted = adaptSheetCatalogue(json, options);
      rows = adapted.length ? adapted : null;
    } finally {
      clearTimeout(timer);
    }
  }
  if (!rows) rows = RETAIL_CATALOGUE.map((row) => ({ ...row }));
  return applySocialpanelIdOverlay(rows, options.socialpanelIds);
}

/**
 * Serializer / validator registry keyed by SocialPanel24 `type`.
 * Browser fields are never forwarded unless the type declares them.
 */

import { normalizeNewlineList } from './inputs.js';
import { parseHttpUrl, profileUrl, validatePlatformUrl } from './urls.js';

/** @typedef {'url'|'username'|'comments'|'usernames'|'hashtags'|'hashtag'|'media'|'groups'|'runs'|'interval'|'country'|'device'|'type_of_traffic'|'google_keyword'|'referring_url'} InputName */

/**
 * @typedef {{
 *   id: string,
 *   label: string,
 *   storefrontInputs: InputName[],
 *   quantityMode: 'required'|'omit'|'from_comments'|'package',
 *   enabled: boolean,
 *   serialize: (ctx: SerializeCtx) => Record<string, string>,
 *   billableQuantity: (ctx: SerializeCtx) => number
 * }} ProviderTypeHandler
 *
 * @typedef {{
 *   platform: string,
 *   quantity: number,
 *   inputs: Record<string, string>,
 *   drip?: { runs?: number, interval?: number }
 * }} SerializeCtx
 */

const WEB_TRAFFIC_DEVICES = new Set(['1', '2', '3', '4', '5']);

/**
 * @param {SerializeCtx} ctx
 * @returns {string}
 */
function resolveLink(ctx) {
  const url = String(ctx.inputs.url || '').trim();
  if (url) {
    const parsed = parseHttpUrl(url);
    if (!parsed) throw new Error('A valid http(s) URL is required.');
    const check = validatePlatformUrl(parsed.href, ctx.platform);
    if (!check.ok) throw new Error(check.error);
    return check.href;
  }
  const fromUsername = profileUrl(ctx.platform, ctx.inputs.username || '');
  if (fromUsername) return fromUsername;
  throw new Error('A target URL or username is required.');
}

/**
 * @param {unknown} value
 * @param {string} label
 */
function requireNewlineList(value, label) {
  const list = normalizeNewlineList(value);
  if (!list.count) throw new Error(`${label} is required.`);
  return list;
}

/**
 * @param {SerializeCtx} ctx
 * @param {Record<string, string>} params
 */
function applyDrip(ctx, params) {
  if (!ctx.drip) return;
  if (ctx.drip.runs != null) params.runs = String(ctx.drip.runs);
  if (ctx.drip.interval != null) params.interval = String(ctx.drip.interval);
}

/**
 * @param {string} id
 * @param {Partial<ProviderTypeHandler>} spec
 * @returns {ProviderTypeHandler}
 */
function defineType(id, spec) {
  return {
    id,
    label: spec.label || id,
    storefrontInputs: spec.storefrontInputs || ['url'],
    quantityMode: spec.quantityMode || 'required',
    enabled: spec.enabled !== false,
    serialize: spec.serialize,
    billableQuantity: spec.billableQuantity || ((ctx) => ctx.quantity),
  };
}

/** @type {Record<string, ProviderTypeHandler>} */
export const PROVIDER_TYPES = {
  Default: defineType('Default', {
    storefrontInputs: ['url'],
    serialize(ctx) {
      const params = { link: resolveLink(ctx), quantity: String(ctx.quantity) };
      applyDrip(ctx, params);
      return params;
    },
  }),
  Package: defineType('Package', {
    quantityMode: 'package',
    storefrontInputs: ['url'],
    serialize(ctx) {
      return { link: resolveLink(ctx) };
    },
    billableQuantity() {
      return 1;
    },
  }),
  'Custom Comments': defineType('Custom Comments', {
    quantityMode: 'from_comments',
    storefrontInputs: ['url', 'comments'],
    serialize(ctx) {
      const comments = requireNewlineList(ctx.inputs.comments, 'Comments');
      return { link: resolveLink(ctx), comments: comments.text };
    },
    billableQuantity(ctx) {
      return normalizeNewlineList(ctx.inputs.comments).count;
    },
  }),
  'Custom Comments Package': defineType('Custom Comments Package', {
    quantityMode: 'package',
    storefrontInputs: ['url', 'comments'],
    serialize(ctx) {
      const comments = requireNewlineList(ctx.inputs.comments, 'Comments');
      return { link: resolveLink(ctx), comments: comments.text };
    },
    billableQuantity() {
      return 1;
    },
  }),
  Mentions: defineType('Mentions', {
    storefrontInputs: ['url', 'usernames'],
    serialize(ctx) {
      const usernames = requireNewlineList(ctx.inputs.usernames, 'Usernames');
      return {
        link: resolveLink(ctx),
        quantity: String(ctx.quantity),
        usernames: usernames.text,
      };
    },
  }),
  'Mentions with Hashtags': defineType('Mentions with Hashtags', {
    storefrontInputs: ['url', 'usernames', 'hashtags'],
    serialize(ctx) {
      const usernames = requireNewlineList(ctx.inputs.usernames, 'Usernames');
      const hashtags = requireNewlineList(ctx.inputs.hashtags, 'Hashtags');
      return {
        link: resolveLink(ctx),
        quantity: String(ctx.quantity),
        usernames: usernames.text,
        hashtags: hashtags.text,
      };
    },
  }),
  'Mentions Custom List': defineType('Mentions Custom List', {
    quantityMode: 'omit',
    storefrontInputs: ['url', 'usernames'],
    serialize(ctx) {
      const usernames = requireNewlineList(ctx.inputs.usernames, 'Usernames');
      return { link: resolveLink(ctx), usernames: usernames.text };
    },
    billableQuantity(ctx) {
      return Math.max(ctx.quantity, normalizeNewlineList(ctx.inputs.usernames).count);
    },
  }),
  'Mentions Hashtag': defineType('Mentions Hashtag', {
    storefrontInputs: ['url', 'hashtag'],
    serialize(ctx) {
      const hashtag = String(ctx.inputs.hashtag || '').replace(/^#/, '').trim();
      if (!hashtag) throw new Error('A hashtag is required.');
      return { link: resolveLink(ctx), quantity: String(ctx.quantity), hashtag };
    },
  }),
  'Mentions User Followers': defineType('Mentions User Followers', {
    storefrontInputs: ['url', 'username'],
    serialize(ctx) {
      const source = String(ctx.inputs.username || ctx.inputs.url || '').trim();
      if (!source) throw new Error('A source username or URL is required.');
      const asUrl = parseHttpUrl(source);
      return {
        link: resolveLink(ctx),
        quantity: String(ctx.quantity),
        username: asUrl ? asUrl.href : source.replace(/^@/, ''),
      };
    },
  }),
  'Mentions Media Likers': defineType('Mentions Media Likers', {
    storefrontInputs: ['url', 'media'],
    serialize(ctx) {
      const media = parseHttpUrl(ctx.inputs.media);
      if (!media) throw new Error('A media URL is required.');
      return { link: resolveLink(ctx), quantity: String(ctx.quantity), media: media.href };
    },
  }),
  'Comment Likes': defineType('Comment Likes', {
    storefrontInputs: ['url', 'username'],
    serialize(ctx) {
      const username = String(ctx.inputs.username || '')
        .replace(/^@/, '')
        .trim();
      if (!username) throw new Error('The comment owner username is required.');
      return { link: resolveLink(ctx), quantity: String(ctx.quantity), username };
    },
  }),
  'Invites from Groups': defineType('Invites from Groups', {
    storefrontInputs: ['url', 'groups'],
    serialize(ctx) {
      const groups = requireNewlineList(ctx.inputs.groups, 'Groups');
      return { link: resolveLink(ctx), quantity: String(ctx.quantity), groups: groups.text };
    },
  }),
  'Web Traffic': defineType('Web Traffic', {
    enabled: true,
    storefrontInputs: ['url', 'country', 'device', 'type_of_traffic', 'google_keyword', 'referring_url'],
    serialize(ctx) {
      const country = String(ctx.inputs.country || '').trim();
      const device = String(ctx.inputs.device || '').trim();
      const traffic = String(ctx.inputs.type_of_traffic || '').trim();
      if (!country) throw new Error('A country is required.');
      if (!WEB_TRAFFIC_DEVICES.has(device)) {
        throw new Error('Device must be a numeric code 1–5.');
      }
      if (!['1', '2', '3'].includes(traffic)) {
        throw new Error('type_of_traffic must be 1, 2, or 3.');
      }
      /** @type {Record<string, string>} */
      const params = {
        link: resolveLink(ctx),
        quantity: String(ctx.quantity),
        country,
        device,
        type_of_traffic: traffic,
      };
      if (traffic === '1') {
        const keyword = String(ctx.inputs.google_keyword || '').trim();
        if (!keyword) throw new Error('google_keyword is required for type_of_traffic 1.');
        params.google_keyword = keyword;
      }
      if (traffic === '2') {
        const referring = parseHttpUrl(ctx.inputs.referring_url);
        if (!referring) throw new Error('referring_url is required for type_of_traffic 2.');
        params.referring_url = referring.href;
      }
      applyDrip(ctx, params);
      return params;
    },
  }),
  Subscriptions: defineType('Subscriptions', {
    enabled: false,
    storefrontInputs: ['username'],
    serialize() {
      throw new Error('Subscriptions are unavailable until bounded billing is defined.');
    },
  }),
};

/**
 * @param {string} typeName
 * @returns {ProviderTypeHandler|null}
 */
export function getProviderType(typeName) {
  const name = String(typeName || '').trim();
  if (PROVIDER_TYPES[name]) return PROVIDER_TYPES[name];
  const lower = name.toLowerCase();
  return Object.values(PROVIDER_TYPES).find((entry) => entry.id.toLowerCase() === lower) || null;
}

/**
 * @param {string} typeName
 * @returns {boolean}
 */
export function isSupportedProviderType(typeName) {
  const handler = getProviderType(typeName);
  return Boolean(handler && handler.enabled);
}

/**
 * Build add-action fields excluding key/action/service (those are added server-side).
 * @param {string} typeName
 * @param {SerializeCtx} ctx
 * @returns {Record<string, string>}
 */
export function serializeProviderAdd(typeName, ctx) {
  const handler = getProviderType(typeName);
  if (!handler || !handler.enabled) {
    throw new Error(`Unsupported provider type: ${typeName || '(missing)'}`);
  }
  return handler.serialize(ctx);
}

/**
 * @param {string} typeName
 * @param {SerializeCtx} ctx
 * @returns {number}
 */
export function billableQuantityForType(typeName, ctx) {
  const handler = getProviderType(typeName);
  if (!handler) throw new Error(`Unsupported provider type: ${typeName || '(missing)'}`);
  const qty = handler.billableQuantity(ctx);
  if (!Number.isInteger(qty) || qty < 1) throw new Error('Invalid billable quantity.');
  return qty;
}

/**
 * Canonical storefront / provider input names and aliases.
 * Browser aliases such as commentsList are mapped to `comments`.
 */

/** @type {Readonly<Record<string, string>>} */
export const INPUT_ALIASES = Object.freeze({
  url: 'url',
  link: 'url',
  username: 'username',
  comments: 'comments',
  commentslist: 'comments',
  comment_list: 'comments',
  usernames: 'usernames',
  hashtags: 'hashtags',
  hashtag: 'hashtag',
  media: 'media',
  groups: 'groups',
  runs: 'runs',
  interval: 'interval',
  country: 'country',
  device: 'device',
  type_of_traffic: 'type_of_traffic',
  google_keyword: 'google_keyword',
  referring_url: 'referring_url',
});

/** Names the storefront may collect. */
export const STOREFRONT_INPUTS = Object.freeze([
  'url',
  'username',
  'comments',
  'usernames',
  'hashtags',
  'hashtag',
  'media',
  'groups',
  'runs',
  'interval',
  'country',
  'device',
  'type_of_traffic',
  'google_keyword',
  'referring_url',
]);

/**
 * Canonicalize a single input name.
 * @param {unknown} name
 * @returns {string}
 */
export function canonicalInputName(name) {
  const key = String(name ?? '')
    .trim()
    .replace(/[\s-]+/g, '_')
    .toLowerCase();
  return INPUT_ALIASES[key] || '';
}

/**
 * Parse a comma-separated Inputs cell (sheet compatibility) into canonical names.
 * @param {unknown} raw
 * @returns {string[]}
 */
export function parseInputList(raw) {
  if (Array.isArray(raw)) {
    return unique(raw.map(canonicalInputName).filter(Boolean));
  }
  if (!raw || !String(raw).trim()) return [];
  return unique(
    String(raw)
      .split(',')
      .map((part) => canonicalInputName(part))
      .filter(Boolean)
  );
}

/**
 * Normalize CRLF to LF and keep nonempty comment/list entries unchanged.
 * Blank lines are dropped; remaining text is not trimmed or rewritten.
 * @param {unknown} value
 * @returns {{ text: string, entries: string[], count: number }}
 */
export function normalizeNewlineList(value) {
  const normalized = String(value ?? '')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n');
  const entries = normalized.split('\n').filter((line) => line.trim().length > 0);
  return {
    text: entries.join('\n'),
    entries,
    count: entries.length,
  };
}

/**
 * Map a raw input object onto canonical keys. Unknown keys are dropped.
 * @param {unknown} inputs
 * @returns {Record<string, string>}
 */
export function canonicalizeInputValues(inputs) {
  /** @type {Record<string, string>} */
  const out = {};
  if (!inputs || typeof inputs !== 'object') return out;
  Object.entries(/** @type {Record<string, unknown>} */ (inputs)).forEach(([key, value]) => {
    const name = canonicalInputName(key);
    if (!name) return;
    if (name === 'comments' || name === 'usernames' || name === 'hashtags' || name === 'groups') {
      out[name] = normalizeNewlineList(value).text;
      return;
    }
    if (name === 'username') {
      out[name] = String(value ?? '')
        .replace(/^@/, '')
        .trim();
      return;
    }
    out[name] = String(value ?? '').trim();
  });
  return out;
}

/**
 * @param {string[]} names
 * @returns {string[]}
 */
function unique(names) {
  return [...new Set(names)];
}

/**
 * Platform host allowlists. Validation uses URL parsing, not substring matching.
 */

/** @type {Readonly<Record<string, readonly string[]>>} */
export const PLATFORM_HOSTS = Object.freeze({
  instagram: Object.freeze(['instagram.com', 'instagr.am']),
  tiktok: Object.freeze(['tiktok.com']),
  youtube: Object.freeze(['youtube.com', 'youtu.be', 'youtube-nocookie.com']),
  facebook: Object.freeze(['facebook.com', 'fb.com', 'fb.watch']),
});

/**
 * @param {unknown} value
 * @returns {URL|null}
 */
export function parseHttpUrl(value) {
  const raw = String(value ?? '').trim();
  if (!raw) return null;
  try {
    const url = new URL(raw);
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
    if (!url.hostname) return null;
    return url;
  } catch {
    return null;
  }
}

/**
 * Host match: exact registrable suffix, never a substring of an unrelated host.
 * @param {string} hostname
 * @param {readonly string[]} allowed
 * @returns {boolean}
 */
export function hostAllowed(hostname, allowed) {
  const host = String(hostname || '')
    .trim()
    .toLowerCase()
    .replace(/\.$/, '');
  if (!host) return false;
  return allowed.some((entry) => host === entry || host.endsWith(`.${entry}`));
}

/**
 * @param {unknown} value
 * @param {string} platform
 * @returns {{ ok: true, href: string }|{ ok: false, error: string }}
 */
export function validatePlatformUrl(value, platform) {
  const url = parseHttpUrl(value);
  if (!url) {
    return { ok: false, error: 'Please enter a valid http(s) URL.' };
  }
  const hosts = PLATFORM_HOSTS[platform];
  if (hosts && !hostAllowed(url.hostname, hosts)) {
    return {
      ok: false,
      error: `That URL must be a ${platform} link.`,
    };
  }
  return { ok: true, href: url.href };
}

/**
 * Build a profile URL from a username when the service has no post URL.
 * @param {string} platform
 * @param {string} username
 * @returns {string}
 */
export function profileUrl(platform, username) {
  const handle = String(username ?? '')
    .replace(/^@/, '')
    .trim();
  if (!handle) return '';
  switch (platform) {
    case 'instagram':
      return `https://instagram.com/${encodeURIComponent(handle)}`;
    case 'tiktok':
      return `https://www.tiktok.com/@${encodeURIComponent(handle)}`;
    case 'youtube':
      return `https://www.youtube.com/@${encodeURIComponent(handle)}`;
    case 'facebook':
      return `https://www.facebook.com/${encodeURIComponent(handle)}`;
    default:
      return '';
  }
}
